--
-- Name: _search_place_feedback_recalc(integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._search_place_feedback_recalc(p_impr integer, p_clk integer, p_sav integer, p_chk integer) RETURNS TABLE(ctr_out double precision, score_out double precision)
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT
    CASE WHEN p_impr > 0 THEN (p_clk::double precision / p_impr) ELSE 0::double precision END,
    (p_clk * 1.0 + p_sav * 3.0 + p_chk * 5.0)::double precision;
$$;


