-- Name: admin_audit_log_insert_definer(uuid, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_audit_log_insert_definer(p_actor_id uuid, p_action text, p_target_user_id uuid, p_meta jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
