--
-- Name: approve_curator_application(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_curator_application(application_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  applicant_user_id uuid;
  applicant_name text;
  curator_slug text;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'auth required';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.profiles pr
    WHERE pr.id = auth.uid() AND pr.role = 'admin'
  ) THEN
    RAISE EXCEPTION 'admin only';
  END IF;

  SELECT user_id, name
  INTO applicant_user_id, applicant_name
  FROM public.curator_applications
  WHERE id = application_id
    AND status = 'pending';

  IF applicant_user_id IS NULL THEN
    RAISE EXCEPTION 'Invalid or already processed application';
  END IF;

  curator_slug := lower(
    regexp_replace(COALESCE(applicant_name, 'curator'), '[^a-z0-9가-힣]+', '_', 'g')
  );
  IF curator_slug = '' OR curator_slug = '_' THEN
    curator_slug := 'curator_' || left(replace(applicant_user_id::text, '-', ''), 8);
  END IF;

  -- profiles.role 은 바꾸지 않고 curators 행만 추가/갱신
  INSERT INTO public.curators (user_id, name, display_name, slug)
  VALUES (
    applicant_user_id,
    applicant_name,
    applicant_name,
    curator_slug
  )
  ON CONFLICT (user_id) DO UPDATE SET
    name = EXCLUDED.name,
    display_name = EXCLUDED.display_name,
    slug = EXCLUDED.slug,
    updated_at = now();

  UPDATE public.curator_applications
  SET
    status = 'approved',
    updated_at = now()
  WHERE id = application_id;
END;
$$;


--
-- Name: FUNCTION approve_curator_application(application_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.approve_curator_application(application_id uuid) IS '관리자만: pending 신청 승인 → curators 행 upsert (profiles.role 미변경)';


--
-- Name: check_alpha_access_allowed(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_alpha_access_allowed() RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_email text;
  v_uid uuid;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RETURN false;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.profiles p
    WHERE p.id = v_uid
      AND p.role = 'admin'
  ) THEN
    RETURN true;
  END IF;

  v_email := lower(trim(coalesce(auth.jwt() ->> 'email', '')));
  IF v_email = '' THEN
    RETURN false;
  END IF;

  RETURN EXISTS (
    SELECT 1
    FROM public.alpha_access_allowlist a
    WHERE a.email = v_email
  );
END;
$$;


