-- Name: curator_course_places_block_imported_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.curator_course_places_block_imported_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_course_id uuid;
BEGIN
  IF current_setting('app.allow_import_places', true) = '1' THEN
    IF TG_OP = 'DELETE' THEN
      RETURN OLD;
    END IF;
    RETURN NEW;
  END IF;

  v_course_id := COALESCE(NEW.course_id, OLD.course_id);
  IF EXISTS (
    SELECT 1
    FROM public.curator_courses cc
    WHERE cc.id = v_course_id
      AND cc.imported_from_course_id IS NOT NULL
  ) THEN
    RAISE EXCEPTION '가져온 코스의 장소는 변경할 수 없습니다.';
  END IF;
  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: curator_course_places_enforce_max_six(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.curator_course_places_enforce_max_six() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  n integer;
BEGIN
  SELECT count(*)::integer INTO n
  FROM public.curator_course_places
  WHERE course_id = NEW.course_id;

  IF n >= 6 THEN
    RAISE EXCEPTION 'curator_course_places: a course may have at most 6 places'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


