--
-- Name: curator_place_jsonb_arr_to_space_text(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.curator_place_jsonb_arr_to_space_text(j jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE
    WHEN j IS NULL OR jsonb_typeof(j) <> 'array' THEN ''
    ELSE COALESCE((
      SELECT string_agg(elem, ' ')
      FROM jsonb_array_elements_text(j) AS t(elem)
    ), '')
  END;
$$;


--
-- Name: FUNCTION curator_place_jsonb_arr_to_space_text(j jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.curator_place_jsonb_arr_to_space_text(j jsonb) IS 'curator_place_search_blob: jsonb 배열 → 공백 구분 문자열';


--
-- Name: curator_place_jsonb_facet_text(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.curator_place_jsonb_facet_text(j jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE
    WHEN j IS NULL THEN ''
    WHEN jsonb_typeof(j) = 'null' THEN ''
    WHEN jsonb_typeof(j) = 'array' THEN COALESCE((
      SELECT string_agg(e, ' ')
      FROM jsonb_array_elements_text(j) AS t(e)
    ), '')
    WHEN jsonb_typeof(j) = 'string' THEN (j #>> '{}')
    ELSE ''
  END;
$$;


