--
-- Name: enforce_username_change_cooldown(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_username_change_cooldown() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  old_u text;
  new_u text;
  next_ok timestamptz;
  cooldown constant interval := interval '14 days';
BEGIN
  IF TG_OP = 'INSERT' THEN
    new_u := lower(btrim(COALESCE(NEW.username, '')));
    IF new_u <> '' THEN
      NEW.username_changed_at := timezone('utc', now());
    ELSE
      NEW.username_changed_at := NULL;
    END IF;
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    old_u := lower(btrim(COALESCE(OLD.username, '')));
    new_u := lower(btrim(COALESCE(NEW.username, '')));

    IF old_u IS NOT DISTINCT FROM new_u THEN
      RETURN NEW;
    END IF;

    IF OLD.username_changed_at IS NOT NULL
       AND timezone('utc', now()) < OLD.username_changed_at + cooldown THEN
      next_ok := OLD.username_changed_at + cooldown;
      RAISE EXCEPTION
        '핸들(@고유이름)은 14일에 한 번만 바꿀 수 있습니다. 다음 변경 가능: %.',
        to_char(next_ok AT TIME ZONE 'Asia/Seoul', 'YYYY-MM-DD')
        USING ERRCODE = 'P0001';
    END IF;

    IF new_u = '' THEN
      NEW.username_changed_at := OLD.username_changed_at;
    ELSE
      NEW.username_changed_at := timezone('utc', now());
    END IF;
    RETURN NEW;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION enforce_username_change_cooldown(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.enforce_username_change_cooldown() IS 'profiles·curators: username 값이 바뀔 때 14일 쿨다운.';


--
-- Name: enqueue_curator_grade_review(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_curator_grade_review() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  sug text;
  cur text;
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.total_places IS NOT DISTINCT FROM OLD.total_places THEN
    RETURN NEW;
  END IF;

  cur := lower(trim(COALESCE(NEW.grade, 'bronze')));
  sug := public.grade_from_place_count(COALESCE(NEW.total_places, 0));

  IF public.grade_rank(sug) <= public.grade_rank(cur) THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.curator_grade_review_queue (
    curator_user_id,
    current_grade,
    suggested_grade,
    total_places_at_trigger
  )
  VALUES (
    NEW.user_id,
    cur,
    sug,
    COALESCE(NEW.total_places, 0)
  )
  ON CONFLICT (curator_user_id) WHERE (resolved_at IS NULL)
  DO UPDATE SET
    current_grade = EXCLUDED.current_grade,
    suggested_grade = EXCLUDED.suggested_grade,
    total_places_at_trigger = EXCLUDED.total_places_at_trigger,
    created_at = now();

  RETURN NEW;
END;
$$;


--
-- Name: extract_business_name(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.extract_business_name(full_name text) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
  region TEXT;
  pattern TEXT;
  index_val INTEGER;
  clean_name TEXT;
BEGIN
  clean_name := full_name;
  
  -- 지역명 제거
  FOREACH region IN ARRAY ARRAY['강동구', '성북구', '용산구', '중구', '광진구', '서대문구', '영등포구', '성동구', '동작구', '송파구', '마포구', '은평구', '서초구', '강남구', '관악구', '강서구', '노원구', '종로구', '중랑구', '강북구', '도봉구', '양천구', '구로구', '금천구', '동대문구', '강남구', '영등포구']
  LOOP
    clean_name := regexp_replace(clean_name, region, '', 'g');
    clean_name := trim(clean_name);
  END LOOP;
  
  -- 상호명 추출 (테라스, 야장 등 패턴 찾기)
  FOREACH pattern IN ARRAY ARRAY['테라스', '야장', '루프탑', '펍', '바', '가든', '카페', '집', '골목']
  LOOP
    index_val := strpos(clean_name, pattern);
    IF index_val > 0 THEN
      RETURN trim(substring(clean_name FROM 1 FOR index_val + length(pattern) - 1));
    END IF;
  END LOOP;
  
  -- 패턴이 없으면 전체 반환
  RETURN trim(clean_name);
END;
$$;


