CREATE FUNCTION public.get_course_completion_stats(p_course_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT jsonb_build_object(
    'completion_count', COALESCE(COUNT(*), 0)::bigint,
    'unique_user_count', COALESCE(COUNT(DISTINCT user_id), 0)::bigint,
    'recent_completion_count_7d',
    COALESCE(
      COUNT(*) FILTER (
        WHERE completed_at >= (now() AT TIME ZONE 'utc') - interval '7 days'
      ),
      0
    )::bigint
  )
  FROM public.completed_course_logs
  WHERE course_id IS NOT DISTINCT FROM p_course_id;
$$;


--
-- Name: FUNCTION get_course_completion_stats(p_course_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_course_completion_stats(p_course_id uuid) IS '공개: 코스별 완주 건수·고유 유저·최근 7일 완주 건수 (completed_course_logs 집계).';


--
-- Name: get_course_completion_stats_batch(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_course_completion_stats_batch(p_course_ids uuid[]) RETURNS TABLE(course_id uuid, completion_count bigint, unique_user_count bigint, recent_completion_count_7d bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH wanted AS (
    SELECT DISTINCT x AS course_id
    FROM unnest(COALESCE(p_course_ids, ARRAY[]::uuid[])) AS t(x)
  ),
  agg AS (
    SELECT
      l.course_id,
      COUNT(*)::bigint AS completion_count,
      COUNT(DISTINCT l.user_id)::bigint AS unique_user_count,
      COUNT(*) FILTER (
        WHERE l.completed_at >= (now() AT TIME ZONE 'utc') - interval '7 days'
      )::bigint AS recent_completion_count_7d
    FROM public.completed_course_logs l
    WHERE l.course_id = ANY (SELECT w.course_id FROM wanted w)
    GROUP BY l.course_id
  )
  SELECT
    w.course_id,
    COALESCE(a.completion_count, 0)::bigint,
    COALESCE(a.unique_user_count, 0)::bigint,
    COALESCE(a.recent_completion_count_7d, 0)::bigint
  FROM wanted w
  LEFT JOIN agg a ON a.course_id = w.course_id;
$$;


--
-- Name: FUNCTION get_course_completion_stats_batch(p_course_ids uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_course_completion_stats_batch(p_course_ids uuid[]) IS '공개: 여러 코스에 대한 완주 집계 한 번에 조회.';


