--
-- Name: get_hot_places(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_hot_places() RETURNS TABLE(place_id character varying, place_name character varying, place_address text, recent_checkins_count bigint, latest_checkin_time timestamp with time zone)
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    ci.place_id,
    ci.place_name,
    ci.place_address,
    COUNT(*) as recent_checkins_count,
    MAX(ci.created_at) as latest_checkin_time
  FROM check_ins ci
  WHERE ci.created_at >= NOW() - INTERVAL '3 hours'
  GROUP BY ci.place_id, ci.place_name, ci.place_address
  HAVING COUNT(*) >= 3
  ORDER BY recent_checkins_count DESC, latest_checkin_time DESC;
END;
$$;


--
-- Name: get_mutual_checkins(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_mutual_checkins(limit_count integer DEFAULT 24) RETURNS TABLE(user_id uuid, place_id uuid, raw_place_name text, raw_address text, created_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    l.user_id,
    l.place_id,
    l.raw_place_name,
    l.raw_address,
    l.created_at
  FROM public.user_activity_logs l
  WHERE l.type = 'checkin'
    AND (auth.uid() IS NOT NULL)
    AND l.user_id IN (
      SELECT m.user_id FROM public.get_mutual_users() AS m
    )
    AND l.created_at > timezone('utc', now()) - INTERVAL '12 hours'
  ORDER BY l.created_at DESC
  LIMIT GREATEST(1, LEAST(COALESCE(NULLIF(limit_count, 0), 24), 30));
$$;


