--
-- Name: get_place_density_in_bounds(double precision, double precision, double precision, double precision, integer, double precision); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_place_density_in_bounds(south double precision, west double precision, north double precision, east double precision, p_level integer DEFAULT 8, p_cell_size double precision DEFAULT NULL::double precision) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  lat_min double precision;
  lat_max double precision;
  lng_min double precision;
  lng_max double precision;
  lat_span double precision;
  lng_span double precision;
  span double precision;
  cell double precision;
  lv int := greatest(1, least(coalesce(p_level, 8), 14));
  target_side double precision;
  min_cell double precision;
  max_cell double precision;
  total_cnt int := 0;
BEGIN
  lat_min := LEAST(south, north);
  lat_max := GREATEST(south, north);
  lng_min := LEAST(west, east);
  lng_max := GREATEST(west, east);
  lat_span := lat_max - lat_min;
  lng_span := lng_max - lng_min;
  span := GREATEST(lat_span, lng_span, 0.004);

  IF span > 3.0 THEN
    RAISE EXCEPTION 'bounds_too_large' USING ERRCODE = '22023';
  END IF;

  IF p_cell_size IS NOT NULL AND p_cell_size > 0 THEN
    cell := p_cell_size;
  ELSE
    target_side := CASE
      WHEN lv >= 11 THEN 3.8
      WHEN lv >= 10 THEN 4.2
      WHEN lv >= 9 THEN 4.8
      WHEN lv >= 8 THEN 5.4
      WHEN lv >= 7 THEN 6.0
      WHEN lv >= 6 THEN 6.8
      ELSE 7.5
    END;
    min_cell := CASE
      WHEN lv >= 11 THEN 0.04
      WHEN lv >= 10 THEN 0.028
      WHEN lv >= 9 THEN 0.018
      WHEN lv >= 8 THEN 0.011
      WHEN lv >= 7 THEN 0.007
      WHEN lv >= 6 THEN 0.0045
      ELSE 0.003
    END;
    max_cell := CASE WHEN lv >= 10 THEN 0.14 WHEN lv >= 8 THEN 0.09 ELSE 0.06 END;
    cell := GREATEST(min_cell, LEAST(max_cell, span / target_side));
  END IF;

  SELECT count(*)::int INTO total_cnt
  FROM public.places p
  WHERE p.lat IS NOT NULL
    AND p.lng IS NOT NULL
    AND p.lat BETWEEN lat_min AND lat_max
    AND p.lng BETWEEN lng_min AND lng_max;

  RETURN (
    WITH grid AS (
      SELECT
        floor((p.lat - lat_min) / cell)::int AS gy,
        floor((p.lng - lng_min) / cell)::int AS gx,
        avg(p.lat)::double precision AS lat,
        avg(p.lng)::double precision AS lng,
        count(*)::int AS cnt
      FROM public.places p
      WHERE p.lat IS NOT NULL
        AND p.lng IS NOT NULL
        AND p.lat BETWEEN lat_min AND lat_max
        AND p.lng BETWEEN lng_min AND lng_max
      GROUP BY gy, gx
      HAVING count(*) >= 1
      ORDER BY cnt DESC
      LIMIT 80
    )
    SELECT json_build_object(
      'clusters',
        coalesce(
          (SELECT json_agg(
            json_build_object('lat', g.lat, 'lng', g.lng, 'count', g.cnt)
            ORDER BY g.cnt DESC
          ) FROM grid g),
          '[]'::json
        ),
      'total_in_bounds', total_cnt,
      'cell_size', cell
    )
  );
END;
$$;


--
-- Name: FUNCTION get_place_density_in_bounds(south double precision, west double precision, north double precision, east double precision, p_level integer, p_cell_size double precision); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_place_density_in_bounds(south double precision, west double precision, north double precision, east double precision, p_level integer, p_cell_size double precision) IS '지도 bbox 적응형 그리드 집계 — 줌 아웃 숫자 클러스터. service_role 전용.';


--
-- Name: get_place_hanjan_stats(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_place_hanjan_stats(p_place_id text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH base AS (
    SELECT ci.*
    FROM public.check_ins ci
    WHERE btrim(ci.place_id) = btrim(p_place_id)
  ),
  ded AS (
    SELECT DISTINCT
      COALESCE(user_id::text, 'n:' || lower(btrim(user_nickname))) AS ukey,
      (created_at AT TIME ZONE 'Asia/Seoul')::date AS d
    FROM base
  ),
  ded_near AS (
    SELECT DISTINCT
      COALESCE(user_id::text, 'n:' || lower(btrim(user_nickname))) AS ukey,
      (created_at AT TIME ZONE 'Asia/Seoul')::date AS d
    FROM base
    WHERE distance_meters IS NOT NULL
  ),
  fire AS (
    SELECT DISTINCT
      COALESCE(user_id::text, 'n:' || lower(btrim(user_nickname))) AS ukey,
      (created_at AT TIME ZONE 'Asia/Seoul')::date AS d
    FROM base
    WHERE created_at >= (now() AT TIME ZONE 'utc') - interval '24 hours'
  ),
  fire_today AS (
    SELECT DISTINCT
      COALESCE(user_id::text, 'n:' || lower(btrim(user_nickname))) AS ukey,
      (created_at AT TIME ZONE 'Asia/Seoul')::date AS d
    FROM base
    WHERE (created_at AT TIME ZONE 'Asia/Seoul')::date =
          (now() AT TIME ZONE 'Asia/Seoul')::date
  ),
  reg_users AS (
    SELECT
      COALESCE(user_id::text, 'n:' || lower(btrim(user_nickname))) AS ukey
    FROM base
    WHERE distance_meters IS NOT NULL
    GROUP BY 1
    HAVING COUNT(DISTINCT (created_at AT TIME ZONE 'Asia/Seoul')::date) >= 3
  )
  SELECT jsonb_build_object(
    'total_dedup', (SELECT COUNT(*)::int FROM ded),
    'nearby_dedup', (SELECT COUNT(*)::int FROM ded_near),
    'fire_24h_dedup', (SELECT COUNT(*)::int FROM fire),
    'fire_today_dedup', (SELECT COUNT(*)::int FROM fire_today),
    'regulars_nearby', (SELECT COUNT(*)::int FROM reg_users),
    'last_at', (SELECT max(created_at) FROM base)
  );
$$;


--
-- Name: FUNCTION get_place_hanjan_stats(p_place_id text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_place_hanjan_stats(p_place_id text) IS '장소 카드용: 한잔 누적(유저+KST일 1회), 여기서 한잔(거리 기록 있음), 24h/오늘 불꽃, 근처 단골(3일+)';


