--
-- Name: get_places_in_bounds(double precision, double precision, double precision, double precision, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_places_in_bounds(south double precision, west double precision, north double precision, east double precision, p_limit integer DEFAULT 80) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  lim int := greatest(1, least(coalesce(nullif(p_limit, 0), 80), 200));
  lat_min double precision;
  lat_max double precision;
  lng_min double precision;
  lng_max double precision;
BEGIN
  lat_min := LEAST(south, north);
  lat_max := GREATEST(south, north);
  lng_min := LEAST(west, east);
  lng_max := GREATEST(west, east);

  IF (lat_max - lat_min) > 3.0 OR (lng_max - lng_min) > 3.0 THEN
    RAISE EXCEPTION 'bounds_too_large' USING ERRCODE = '22023';
  END IF;

  RETURN (
    WITH bbox_places AS (
      SELECT
        p.id,
        p.name,
        p.category,
        p.lat,
        p.lng,
        p.tags,
        coalesce(p.address, '') AS address,
        ''::text AS address_name,
        ''::text AS road_address_name,
        ''::text AS place_url,
        p.kakao_place_id
      FROM public.places p
      WHERE p.lat BETWEEN lat_min AND lat_max
        AND p.lng BETWEEN lng_min AND lng_max
    ),
    curator_counts AS (
      SELECT
        cp.place_id,
        count(*)::int AS curator_cnt
      FROM public.curator_places cp
      INNER JOIN bbox_places bp ON bp.id = cp.place_id
      WHERE cp.is_archived IS DISTINCT FROM TRUE
      GROUP BY cp.place_id
    ),
    cand AS (
      SELECT
        bp.id,
        bp.name,
        bp.category,
        bp.lat,
        bp.lng,
        bp.tags,
        bp.address,
        bp.address_name,
        bp.road_address_name,
        bp.place_url,
        bp.kakao_place_id,
        coalesce(cc.curator_cnt, 0) AS curator_cnt
      FROM bbox_places bp
      LEFT JOIN curator_counts cc ON cc.place_id = bp.id
      ORDER BY
        (CASE WHEN coalesce(cc.curator_cnt, 0) > 0 THEN 0 ELSE 1 END),
        coalesce(cc.curator_cnt, 0) DESC,
        bp.id
      LIMIT lim
    ),
    places_json AS (
      SELECT coalesce(
        json_agg(
          json_build_object(
            'id', c.id,
            'name', c.name,
            'category', c.category,
            'lat', c.lat,
            'lng', c.lng,
            'tags', coalesce(to_jsonb(c.tags), '[]'::jsonb),
            'address', c.address,
            'address_name', c.address_name,
            'road_address_name', c.road_address_name,
            'place_url', c.place_url,
            'kakao_place_id',
              CASE
                WHEN c.kakao_place_id IS NULL THEN NULL
                ELSE c.kakao_place_id::text
              END
          )
          ORDER BY c.curator_cnt DESC, c.id
        ),
        '[]'::json
      ) AS j
      FROM cand c
    ),
    join_rows_json AS (
      SELECT coalesce(
        json_agg(
          json_build_object(
            'place_id', cp.place_id,
            'is_archived', (cp.is_archived IS TRUE),
            'one_line_reason', coalesce(cp.one_line_reason, ''),
            'menu_reason', ''::text,
            'one_line_review', coalesce(cp.one_line_review, ''),
            'tags', coalesce(to_jsonb(cp.tags), '[]'::jsonb),
            'moods', coalesce(to_jsonb(cp.moods), '[]'::jsonb),
            'curators', json_build_object(
              'username', coalesce(cu.username, ''),
              'display_name', coalesce(cu.display_name, '')
            ),
            'places', json_build_object(
              'id', p.id,
              'name', p.name,
              'category', p.category,
              'lat', p.lat,
              'lng', p.lng,
              'tags', coalesce(to_jsonb(p.tags), '[]'::jsonb),
              'address', coalesce(p.address, ''),
              'address_name', ''::text,
              'road_address_name', ''::text,
              'place_url', ''::text,
              'kakao_place_id',
                CASE
                  WHEN p.kakao_place_id IS NULL THEN NULL
                  ELSE p.kakao_place_id::text
                END
            )
          )
        ),
        '[]'::json
      ) AS j
      FROM public.curator_places cp
      INNER JOIN cand ON cand.id = cp.place_id
      INNER JOIN public.places p ON p.id = cp.place_id
      INNER JOIN public.curators cu ON cu.user_id = cp.curator_id
      WHERE cp.is_archived IS DISTINCT FROM TRUE
    )
    SELECT json_build_object(
      'places', (SELECT j FROM places_json),
      'join_rows', (SELECT j FROM join_rows_json)
    )
  );
END;
$$;


--
-- Name: FUNCTION get_places_in_bounds(south double precision, west double precision, north double precision, east double precision, p_limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_places_in_bounds(south double precision, west double precision, north double precision, east double precision, p_limit integer) IS '지도 bbox: bbox 내 places 먼저 → 큐레이터 수 우선 상한(최대 200). service_role 전용.';


--
-- Name: get_search_social_boost_batch(uuid[], text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_search_social_boost_batch(p_place_uuids uuid[], p_hanjan_place_keys text[]) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT jsonb_build_object(
    'picks',
    COALESCE(
      (
        SELECT jsonb_object_agg(sub.place_id::text, sub.w)
        FROM (
          SELECT
            pp.place_id,
            SUM(CASE WHEN pp.is_curator THEN 4 ELSE 1 END)::int AS w
          FROM public.place_picks pp
          WHERE
            p_place_uuids IS NOT NULL
            AND cardinality(p_place_uuids) > 0
            AND pp.place_id = ANY(p_place_uuids)
          GROUP BY pp.place_id
        ) sub
      ),
      '{}'::jsonb
    ),
    'hanjan',
    COALESCE(
      (
        SELECT jsonb_object_agg(sub.k, sub.c)
        FROM (
          SELECT
            btrim(ci.place_id) AS k,
            COUNT(*)::int AS c
          FROM public.check_ins ci
          WHERE
            p_hanjan_place_keys IS NOT NULL
            AND cardinality(p_hanjan_place_keys) > 0
            AND btrim(ci.place_id) IN (
              SELECT btrim(x)
              FROM unnest(p_hanjan_place_keys) AS u(x)
            )
          GROUP BY btrim(ci.place_id)
        ) sub
      ),
      '{}'::jsonb
    )
  );
$$;


--
-- Name: FUNCTION get_search_social_boost_batch(p_place_uuids uuid[], p_hanjan_place_keys text[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_search_social_boost_batch(p_place_uuids uuid[], p_hanjan_place_keys text[]) IS '검색 후보 배치용: place_picks 가중 합 + check_ins 건수. 클라이언트에서 log·cap 보정.';


--
-- Name: get_studio_ai_course_suggestion_quota(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_studio_ai_course_suggestion_quota(p_user_id uuid DEFAULT auth.uid()) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := p_user_id;
  v_limit integer := 5;
  v_used integer;
  v_pro boolean;
BEGIN
  IF v_uid IS NULL OR v_uid IS DISTINCT FROM auth.uid() THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'forbidden');
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.curators c WHERE c.user_id = v_uid
  ) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_curator');
  END IF;

  v_pro := public.is_studio_pro_curator(v_uid);
  v_used := public._studio_ai_course_used_this_month(v_uid);

  RETURN jsonb_build_object(
    'ok', true,
    'is_pro', v_pro,
    'limit', CASE WHEN v_pro THEN NULL ELSE v_limit END,
    'used', v_used,
    'remaining',
      CASE WHEN v_pro THEN NULL ELSE greatest(0, v_limit - v_used) END,
    'period_label',
      to_char(
        public._studio_ai_course_month_start_kst() AT TIME ZONE 'Asia/Seoul',
        'YYYY-MM'
      )
  );
END;
$$;


--
-- Name: FUNCTION get_studio_ai_course_suggestion_quota(p_user_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_studio_ai_course_suggestion_quota(p_user_id uuid) IS '큐레이터 AI 코스 초안 — 이번 달 사용량(무료 5회 / Pro 무제한).';


--
-- Name: get_user_saved_places_with_folders(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_user_saved_places_with_folders(p_user_id uuid) RETURNS TABLE(place_id uuid, place_name text, place_lat numeric, place_lng numeric, saved_at timestamp with time zone, folder_keys text[], folder_names text[])
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        p.id,
        p.name,
        p.lat,
        p.lng,
        usp.created_at,
        ARRAY_AGG(DISTINCT uspf.folder_key) as folder_keys,
        ARRAY_AGG(DISTINCT sf.name) as folder_names
    FROM user_saved_places usp
    JOIN places p ON usp.place_id = p.id
    LEFT JOIN user_saved_place_folders uspf ON usp.id = uspf.user_saved_place_id
    LEFT JOIN system_folders sf ON uspf.folder_key = sf.key
    WHERE usp.user_id = p_user_id
    GROUP BY p.id, p.name, p.lat, p.lng, usp.created_at
    ORDER BY usp.created_at DESC;
END;
$$;


--
-- Name: get_user_wallet(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_user_wallet(p_user_id uuid DEFAULT auth.uid()) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := p_user_id;
  v_drops integer := 0;
  v_credits integer := 0;
  v_per integer := public._drops_per_ai_credit();
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_authenticated');
  END IF;

  PERFORM public._ensure_user_wallet(v_uid);

  SELECT w.drop_balance, w.ai_credit_balance
  INTO v_drops, v_credits
  FROM public.user_wallets w
  WHERE w.user_id = v_uid;

  RETURN jsonb_build_object(
    'ok', true,
    'drops', COALESCE(v_drops, 0),
    'ai_credits', COALESCE(v_credits, 0),
    'drops_per_ai_credit', v_per,
    'progress_drops', COALESCE(v_drops, 0) % v_per,
    'can_exchange', COALESCE(v_drops, 0) >= v_per
  );
END;
$$;


--
-- Name: grade_from_place_count(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.grade_from_place_count(p_count integer) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE
    WHEN p_count >= 1000 THEN 'diamond'
    WHEN p_count >= 500 THEN 'platinum'
    WHEN p_count >= 200 THEN 'gold'
    WHEN p_count >= 100 THEN 'silver'
    ELSE 'bronze'
  END;
$$;


--
-- Name: grade_rank(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.grade_rank(p_grade text) RETURNS integer
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE lower(trim(COALESCE(p_grade, 'bronze')))
    WHEN 'diamond' THEN 4
    WHEN 'platinum' THEN 3
    WHEN 'gold' THEN 2
    WHEN 'silver' THEN 1
    ELSE 0
  END;
$$;


