--
-- Name: haversine_meters(double precision, double precision, double precision, double precision); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.haversine_meters(lat1 double precision, lon1 double precision, lat2 double precision, lon2 double precision) RETURNS double precision
    LANGUAGE sql IMMUTABLE STRICT
    AS $$
  SELECT (
    2 * 6371000 * asin(
      least(
        1::double precision,
        sqrt(
          power(sin(radians((lat2 - lat1) / 2)), 2)
          + cos(radians(lat1)) * cos(radians(lat2))
            * power(sin(radians((lon2 - lon1) / 2)), 2)
        )
      )
    )
  )::double precision;
$$;


--
-- Name: home_rising_curators(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.home_rising_curators(p_limit integer DEFAULT 8) RETURNS TABLE(curator_id uuid, username text, display_name text, avatar_url text, week_places bigint, week_follows bigint, score numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH lim AS (
    SELECT LEAST(GREATEST(COALESCE(p_limit, 8), 1), 20)::int AS n
  ),
  week_start AS (
    SELECT ((now() AT TIME ZONE 'utc') - interval '7 days') AS t
  ),
  cur AS (
    SELECT
      c.id,
      c.user_id,
      btrim(c.username) AS username_raw,
      COALESCE(NULLIF(btrim(c.display_name), ''), NULLIF(btrim(c.name), ''), btrim(c.username)) AS disp,
      NULLIF(btrim(COALESCE(c.avatar_url, c.image, '')), '') AS av
    FROM curators c
    WHERE c.username IS NOT NULL
      AND btrim(c.username) <> ''
      AND COALESCE(c.status::text, 'active') NOT IN ('suspended', 'inactive')
  ),
  cp_raw AS (
    SELECT cp.curator_id AS raw_id, COUNT(*)::bigint AS cnt
    FROM curator_places cp
    CROSS JOIN week_start w
    WHERE cp.created_at >= w.t
      AND (cp.is_archived IS NOT TRUE)
    GROUP BY cp.curator_id
  ),
  cp_norm AS (
    SELECT c.id AS curator_pk, SUM(r.cnt)::bigint AS week_places
    FROM cp_raw r
    INNER JOIN cur c ON (c.id = r.raw_id OR c.user_id = r.raw_id)
    GROUP BY c.id
  ),
  fol_norm AS (
    SELECT
      uf.curator_id::uuid AS curator_pk,
      COUNT(*)::bigint AS week_follows
    FROM user_follows uf
    CROSS JOIN week_start w
    WHERE uf.created_at >= w.t
      AND uf.curator_id IS NOT NULL
      AND btrim(uf.curator_id::text) <> ''
    GROUP BY uf.curator_id::uuid
  ),
  scored AS (
    SELECT
      c.id AS curator_id,
      c.username_raw::text AS username,
      c.disp::text AS display_name,
      c.av::text AS avatar_url,
      COALESCE(p.week_places, 0::bigint) AS week_places,
      COALESCE(f.week_follows, 0::bigint) AS week_follows,
      (COALESCE(p.week_places, 0::bigint) * 2 + COALESCE(f.week_follows, 0::bigint))::numeric AS score
    FROM cur c
    LEFT JOIN cp_norm p ON p.curator_pk = c.id
    LEFT JOIN fol_norm f ON f.curator_pk = c.id
    WHERE COALESCE(p.week_places, 0) + COALESCE(f.week_follows, 0) > 0
  )
  SELECT
    s.curator_id,
    s.username,
    s.display_name,
    s.avatar_url,
    s.week_places,
    s.week_follows,
    s.score
  FROM scored s
  CROSS JOIN lim
  ORDER BY s.score DESC, s.week_places DESC, s.week_follows DESC, s.display_name ASC
  LIMIT (SELECT n FROM lim);
$$;


--
-- Name: FUNCTION home_rising_curators(p_limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.home_rising_curators(p_limit integer) IS '홈: 최근 7일 공개 잔 수×2 + 팔로 수로 떠오르는 큐레이터';


--
-- Name: import_curator_course_snapshot(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.import_curator_course_snapshot(p_source_course_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_existing uuid;
  v_src public.curator_courses%ROWTYPE;
  v_new_id uuid;
  v_step_count integer;
  v_place_count integer;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION '로그인이 필요합니다.' USING ERRCODE = 'P0001';
  END IF;

  IF p_source_course_id IS NULL THEN
    RAISE EXCEPTION '코스 ID가 올바르지 않습니다.' USING ERRCODE = 'P0001';
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtext(v_user::text || ':' || p_source_course_id::text)
  );

  SELECT cc.id INTO v_existing
  FROM public.curator_courses cc
  WHERE cc.curator_id = v_user
    AND cc.imported_from_course_id = p_source_course_id
  LIMIT 1;

  IF v_existing IS NOT NULL THEN
    RETURN v_existing;
  END IF;

  SELECT * INTO v_src
  FROM public.curator_courses
  WHERE id = p_source_course_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION '코스를 찾을 수 없습니다.' USING ERRCODE = 'P0001';
  END IF;

  IF v_src.status <> 'published' OR NOT v_src.is_public THEN
    RAISE EXCEPTION '공개된 코스만 스크랩할 수 있습니다.' USING ERRCODE = 'P0001';
  END IF;

  IF v_src.curator_id = v_user THEN
    RAISE EXCEPTION '내가 만든 코스는 스크랩할 수 없습니다.' USING ERRCODE = 'P0001';
  END IF;

  SELECT count(*)::integer INTO v_step_count
  FROM public.curator_course_places
  WHERE course_id = p_source_course_id;

  IF v_step_count < 1 THEN
    RAISE EXCEPTION '장소가 없는 코스는 스크랩할 수 없습니다.' USING ERRCODE = 'P0001';
  END IF;

  BEGIN
    INSERT INTO public.curator_courses (
      curator_id,
      title,
      description,
      area,
      theme_tags,
      cover_image_url,
      status,
      is_public,
      imported_from_course_id
    )
    VALUES (
      v_user,
      v_src.title,
      v_src.description,
      v_src.area,
      COALESCE(v_src.theme_tags, '{}'::text[]),
      v_src.cover_image_url,
      'private',
      false,
      p_source_course_id
    )
    RETURNING id INTO v_new_id;
  EXCEPTION
    WHEN unique_violation THEN
      SELECT cc.id INTO v_new_id
      FROM public.curator_courses cc
      WHERE cc.curator_id = v_user
        AND cc.imported_from_course_id = p_source_course_id
      LIMIT 1;
      IF v_new_id IS NULL THEN
        RAISE;
      END IF;
  END;

  SELECT count(*)::integer INTO v_place_count
  FROM public.curator_course_places
  WHERE course_id = v_new_id;

  IF v_place_count = 0 THEN
    PERFORM set_config('app.allow_import_places', '1', true);

    INSERT INTO public.curator_course_places (
      course_id,
      place_id,
      order_index,
      memo,
      image_url,
      stay_minutes
    )
    SELECT
      v_new_id,
      ccp.place_id,
      ccp.order_index,
      ccp.memo,
      ccp.image_url,
      ccp.stay_minutes
    FROM public.curator_course_places ccp
    WHERE ccp.course_id = p_source_course_id
    ORDER BY ccp.order_index;

    PERFORM set_config('app.allow_import_places', '0', true);
  END IF;

  RETURN v_new_id;
END;
$$;


--
-- Name: increment_search_place_feedback_click(text, text, text[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.increment_search_place_feedback_click(p_normalized_query text, p_area text, p_intent_tags text[], p_place_key text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_impr int;
  v_clk int;
  v_sav int;
  v_chk int;
  v_ctr double precision;
  v_score double precision;
  v_pu uuid;
  bk text;
BEGIN
  bk := btrim(p_place_key);
  IF p_normalized_query IS NULL OR btrim(p_normalized_query) = '' OR bk = '' THEN
    RETURN;
  END IF;
  v_pu := NULL;
  IF bk ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    BEGIN
      v_pu := bk::uuid;
    EXCEPTION WHEN OTHERS THEN
      v_pu := NULL;
    END;
  END IF;

  INSERT INTO public.search_place_feedback (
    normalized_query, area, intent_tags, place_key, place_uuid,
    impression_count, click_count, save_count, checkin_count, ctr, behavior_score, updated_at
  )
  VALUES (
    btrim(p_normalized_query),
    NULLIF(btrim(p_area), ''),
    p_intent_tags,
    bk,
    v_pu,
    0, 1, 0, 0, 0, 0, now()
  )
  ON CONFLICT (normalized_query, place_key) DO UPDATE SET
    click_count = public.search_place_feedback.click_count + 1,
    area = COALESCE(EXCLUDED.area, public.search_place_feedback.area),
    intent_tags = CASE
      WHEN EXCLUDED.intent_tags IS NOT NULL AND cardinality(EXCLUDED.intent_tags) > 0
      THEN EXCLUDED.intent_tags
      ELSE public.search_place_feedback.intent_tags
    END,
    place_uuid = COALESCE(public.search_place_feedback.place_uuid, EXCLUDED.place_uuid),
    updated_at = now();

  SELECT impression_count, click_count, save_count, checkin_count
  INTO v_impr, v_clk, v_sav, v_chk
  FROM public.search_place_feedback
  WHERE normalized_query = btrim(p_normalized_query) AND place_key = bk;

  SELECT ctr_out, score_out INTO v_ctr, v_score
  FROM public._search_place_feedback_recalc(v_impr, v_clk, v_sav, v_chk);

  UPDATE public.search_place_feedback
  SET ctr = v_ctr, behavior_score = v_score
  WHERE normalized_query = btrim(p_normalized_query) AND place_key = bk;
END;
$_$;


--
-- Name: increment_search_place_feedback_impressions(text, text, text[], text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.increment_search_place_feedback_impressions(p_normalized_query text, p_area text, p_intent_tags text[], p_place_keys text[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  k text;
  v_impr int;
  v_clk int;
  v_sav int;
  v_chk int;
  v_ctr double precision;
  v_score double precision;
  v_pu uuid;
BEGIN
  IF p_normalized_query IS NULL OR btrim(p_normalized_query) = '' OR p_place_keys IS NULL THEN
    RETURN;
  END IF;
  FOREACH k IN ARRAY p_place_keys
  LOOP
    IF k IS NULL OR btrim(k) = '' THEN
      CONTINUE;
    END IF;
    v_pu := NULL;
    IF k ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      BEGIN
        v_pu := k::uuid;
      EXCEPTION WHEN OTHERS THEN
        v_pu := NULL;
      END;
    END IF;
    INSERT INTO public.search_place_feedback (
      normalized_query, area, intent_tags, place_key, place_uuid,
      impression_count, click_count, save_count, checkin_count, ctr, behavior_score, updated_at
    )
    VALUES (
      btrim(p_normalized_query),
      NULLIF(btrim(p_area), ''),
      p_intent_tags,
      btrim(k),
      v_pu,
      1, 0, 0, 0, 0, 0, now()
    )
    ON CONFLICT (normalized_query, place_key) DO UPDATE SET
      impression_count = public.search_place_feedback.impression_count + 1,
      area = COALESCE(EXCLUDED.area, public.search_place_feedback.area),
      intent_tags = CASE
        WHEN EXCLUDED.intent_tags IS NOT NULL AND cardinality(EXCLUDED.intent_tags) > 0
        THEN EXCLUDED.intent_tags
        ELSE public.search_place_feedback.intent_tags
      END,
      place_uuid = COALESCE(public.search_place_feedback.place_uuid, EXCLUDED.place_uuid),
      updated_at = now();

    SELECT impression_count, click_count, save_count, checkin_count
    INTO v_impr, v_clk, v_sav, v_chk
    FROM public.search_place_feedback
    WHERE normalized_query = btrim(p_normalized_query) AND place_key = btrim(k);

    SELECT ctr_out, score_out INTO v_ctr, v_score
    FROM public._search_place_feedback_recalc(v_impr, v_clk, v_sav, v_chk);

    UPDATE public.search_place_feedback
    SET ctr = v_ctr, behavior_score = v_score
    WHERE normalized_query = btrim(p_normalized_query) AND place_key = btrim(k);
  END LOOP;
END;
$_$;


--
-- Name: increment_search_place_feedback_save(text, text, text[], text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.increment_search_place_feedback_save(p_normalized_query text, p_area text, p_intent_tags text[], p_place_key text, p_delta integer DEFAULT 1) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_impr int;
  v_clk int;
  v_sav int;
  v_chk int;
  v_ctr double precision;
  v_score double precision;
  v_pu uuid;
  bk text;
  d int;
BEGIN
  bk := btrim(p_place_key);
  d := GREATEST(1, LEAST(COALESCE(p_delta, 1), 20));
  IF p_normalized_query IS NULL OR btrim(p_normalized_query) = '' OR bk = '' THEN
    RETURN;
  END IF;
  v_pu := NULL;
  IF bk ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    BEGIN
      v_pu := bk::uuid;
    EXCEPTION WHEN OTHERS THEN
      v_pu := NULL;
    END;
  END IF;

  INSERT INTO public.search_place_feedback (
    normalized_query, area, intent_tags, place_key, place_uuid,
    impression_count, click_count, save_count, checkin_count, ctr, behavior_score, updated_at
  )
  VALUES (
    btrim(p_normalized_query),
    NULLIF(btrim(p_area), ''),
    p_intent_tags,
    bk,
    v_pu,
    0, 0, d, 0, 0, 0, now()
  )
  ON CONFLICT (normalized_query, place_key) DO UPDATE SET
    save_count = public.search_place_feedback.save_count + d,
    area = COALESCE(EXCLUDED.area, public.search_place_feedback.area),
    intent_tags = CASE
      WHEN EXCLUDED.intent_tags IS NOT NULL AND cardinality(EXCLUDED.intent_tags) > 0
      THEN EXCLUDED.intent_tags
      ELSE public.search_place_feedback.intent_tags
    END,
    place_uuid = COALESCE(public.search_place_feedback.place_uuid, EXCLUDED.place_uuid),
    updated_at = now();

  SELECT impression_count, click_count, save_count, checkin_count
  INTO v_impr, v_clk, v_sav, v_chk
  FROM public.search_place_feedback
  WHERE normalized_query = btrim(p_normalized_query) AND place_key = bk;

  SELECT ctr_out, score_out INTO v_ctr, v_score
  FROM public._search_place_feedback_recalc(v_impr, v_clk, v_sav, v_chk);

  UPDATE public.search_place_feedback
  SET ctr = v_ctr, behavior_score = v_score
  WHERE normalized_query = btrim(p_normalized_query) AND place_key = bk;
END;
$_$;


--
-- Name: insert_place_click_log_analytics(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.insert_place_click_log_analytics(p_row jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_uid text;
BEGIN
  IF p_row IS NULL OR COALESCE(p_row->>'clicked_place_id', '') = '' THEN
    RETURN;
  END IF;

  v_uid := COALESCE(auth.uid()::text, 'anonymous');

  INSERT INTO public.place_click_logs (
    clicked_place_id,
    clicked_curator_id,
    place_name,
    search_session_id,
    search_log_id,
    user_query,
    normalized_query,
    source,
    search_click_path,
    clicked_rank,
    user_visible_candidate_count,
    user_id,
    is_logged_in,
    user_type
  ) VALUES (
    p_row->>'clicked_place_id',
    NULLIF(p_row->>'clicked_curator_id', ''),
    COALESCE(NULLIF(p_row->>'place_name', ''), '(unknown)'),
    NULLIF(p_row->>'search_session_id', '')::uuid,
    CASE
      WHEN p_row ? 'search_log_id' AND (p_row->>'search_log_id') ~ '^[0-9]+$'
        THEN (p_row->>'search_log_id')::bigint
      ELSE NULL
    END,
    NULLIF(p_row->>'user_query', ''),
    NULLIF(p_row->>'normalized_query', ''),
    COALESCE(NULLIF(p_row->>'source', ''), 'search_result'),
    NULLIF(p_row->>'search_click_path', ''),
    CASE
      WHEN p_row ? 'clicked_rank' AND (p_row->>'clicked_rank') ~ '^[0-9]+$'
        THEN (p_row->>'clicked_rank')::integer
      ELSE NULL
    END,
    CASE
      WHEN p_row ? 'user_visible_candidate_count'
        AND (p_row->>'user_visible_candidate_count') ~ '^-?[0-9]+$'
        THEN (p_row->>'user_visible_candidate_count')::integer
      ELSE NULL
    END,
    v_uid,
    auth.uid() IS NOT NULL,
    CASE WHEN auth.uid() IS NOT NULL THEN 'registered' ELSE 'anonymous' END
  );
END;
$_$;


--
-- Name: insert_search_log_analytics(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.insert_search_log_analytics(p_row jsonb) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_id bigint;
  v_uid text;
  v_tags text[];
BEGIN
  IF p_row IS NULL OR COALESCE(p_row->>'user_query', '') = '' THEN
    RETURN NULL;
  END IF;

  v_uid := COALESCE(auth.uid()::text, 'anonymous');

  IF p_row ? 'parsed_tags_normalized' AND jsonb_typeof(p_row->'parsed_tags_normalized') = 'array' THEN
    SELECT COALESCE(array_agg(t), ARRAY[]::text[])
    INTO v_tags
    FROM jsonb_array_elements_text(p_row->'parsed_tags_normalized') AS t;
  ELSE
    v_tags := NULL;
  END IF;

  INSERT INTO public.search_logs (
    session_id,
    user_query,
    normalized_query,
    parsed_region,
    parsed_alcohol,
    parsed_vibe,
    parsed_purpose,
    parsed_food,
    parsed_tags_normalized,
    search_mode,
    had_client_error,
    search_results_ids,
    has_results,
    results_count,
    bookmarked,
    submit_user_visible_candidate_count,
    submit_initial_search_kind,
    submit_keyword_ai_fallback,
    user_id,
    is_logged_in,
    user_type
  ) VALUES (
    NULLIF(p_row->>'session_id', '')::uuid,
    p_row->>'user_query',
    NULLIF(p_row->>'normalized_query', ''),
    NULLIF(p_row->>'parsed_region', ''),
    NULLIF(p_row->>'parsed_alcohol', ''),
    NULLIF(p_row->>'parsed_vibe', ''),
    NULLIF(p_row->>'parsed_purpose', ''),
    NULLIF(p_row->>'parsed_food', ''),
    v_tags,
    NULLIF(p_row->>'search_mode', ''),
    COALESCE((p_row->>'had_client_error')::boolean, false),
    CASE
      WHEN p_row ? 'search_results_ids' AND jsonb_typeof(p_row->'search_results_ids') = 'array'
        THEN ARRAY(SELECT jsonb_array_elements_text(p_row->'search_results_ids'))
      ELSE ARRAY[]::text[]
    END,
    COALESCE((p_row->>'has_results')::boolean, false),
    COALESCE((p_row->>'results_count')::integer, 0),
    false,
    CASE
      WHEN p_row ? 'submit_user_visible_candidate_count'
        AND (p_row->>'submit_user_visible_candidate_count') ~ '^-?[0-9]+$'
        THEN (p_row->>'submit_user_visible_candidate_count')::integer
      ELSE NULL
    END,
    NULLIF(p_row->>'submit_initial_search_kind', ''),
    COALESCE((p_row->>'submit_keyword_ai_fallback')::boolean, false),
    v_uid,
    auth.uid() IS NOT NULL,
    CASE WHEN auth.uid() IS NOT NULL THEN 'registered' ELSE 'anonymous' END
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$_$;


--
-- Name: is_following_curator(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_following_curator(curator_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
begin
  return exists (
    select 1 from public.follows
    where user_id = auth.uid() and curator_id = curator_id
  );
end;
$$;


--
-- Name: is_following_user(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_following_user(p_target_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.user_profile_follows f
    WHERE f.follower_id = auth.uid()
      AND f.following_id = p_target_user_id
  );
$$;


--
-- Name: is_studio_pro_curator(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_studio_pro_curator(p_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.curators c
    WHERE c.user_id = p_user_id
      AND c.studio_pro_until IS NOT NULL
      AND c.studio_pro_until > now()
  );
$$;


--
-- Name: log_checkin_user_activity_row(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_checkin_user_activity_row() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  pid uuid;
  ts timestamptz;
  pname text;
  paddr text;
  pname_from_place text;
BEGIN
  IF NEW.user_id IS NULL THEN
    RETURN NEW;
  END IF;

  ts := COALESCE(NEW.created_at, timezone('utc', now()));

  pname := trim(COALESCE(NEW.place_name, ''));
  paddr := left(trim(COALESCE(NEW.place_address, '')), 500);

  pid := public.resolve_places_uuid_from_check_ins_place_id(NEW.place_id::text);

  IF pid IS NOT NULL THEN
    IF pname = '' THEN
      SELECT trim(COALESCE(p.name::text, '')) INTO pname_from_place
      FROM public.places p
      WHERE p.id = pid
      LIMIT 1;
      pname := COALESCE(NULLIF(pname_from_place, ''), pname);
    END IF;
  END IF;

  IF pname = '' THEN
    pname := trim(COALESCE(NEW.place_id::text, ''));
  END IF;
  IF pname = '' THEN
    pname := '근처 술집';
  END IF;

  pname := left(pname, 500);

  IF pid IS NOT NULL THEN
    IF EXISTS (
      SELECT 1
      FROM public.user_activity_logs u
      WHERE u.user_id = NEW.user_id
        AND u.type = 'checkin'
        AND u.place_id IS NOT DISTINCT FROM pid
        AND u.created_at >= ts - INTERVAL '2 hours'
    ) THEN
      RETURN NEW;
    END IF;

    INSERT INTO public.user_activity_logs (
      user_id,
      type,
      place_id,
      raw_place_name,
      raw_address,
      created_at
    )
    VALUES (
      NEW.user_id,
      'checkin',
      pid,
      pname,
      NULLIF(paddr, ''),
      ts
    );
    RETURN NEW;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.user_activity_logs u
    WHERE u.user_id = NEW.user_id
      AND u.type = 'checkin'
      AND u.place_id IS NULL
      AND left(btrim(lower(COALESCE(u.raw_place_name, ''))), 400)
        = left(btrim(lower(pname)), 400)
      AND u.created_at >= ts - INTERVAL '2 hours'
  ) THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.user_activity_logs (
    user_id,
    type,
    place_id,
    raw_place_name,
    raw_address,
    created_at
  )
  VALUES (
    NEW.user_id,
    'checkin',
    NULL,
    pname,
    NULLIF(paddr, ''),
    ts
  );

  RETURN NEW;
END;
$$;


--
-- Name: map_places_in_bbox(double precision, double precision, double precision, double precision, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.map_places_in_bbox(south double precision, west double precision, north double precision, east double precision, p_limit integer DEFAULT 120, p_situation_key text DEFAULT NULL::text) RETURNS TABLE(id uuid, name text, category text, lat double precision, lng double precision, map_score double precision)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  WITH b AS (
    SELECT
      LEAST(south, north) AS lat_min,
      GREATEST(south, north) AS lat_max,
      LEAST(west, east) AS lng_min,
      GREATEST(west, east) AS lng_max
  ),
  raw AS (
    SELECT
      p.id AS pid,
      p.name AS pname,
      p.category AS pcategory,
      p.lat::double precision AS plat,
      p.lng::double precision AS plng,
      (
        SELECT count(*)::double precision
        FROM curator_places cp
        WHERE cp.place_id = p.id
          AND (cp.is_archived IS NOT TRUE)
      ) AS curator_cnt,
      lower(
        coalesce(p.category, '') || ' ' || coalesce(array_to_string(p.tags, ' '), '')
      ) AS hay
    FROM places p
    CROSS JOIN b
    WHERE p.lat BETWEEN b.lat_min AND b.lat_max
      AND p.lng BETWEEN b.lng_min AND b.lng_max
  ),
  situation_pass AS (
    SELECT
      r.*,
      (
        r.curator_cnt * 2.0
        + 1.0
      ) AS sc
    FROM raw r
    WHERE
      p_situation_key IS NULL
      OR p_situation_key NOT IN ('after_party', 'group', 'date')
      OR (
        (
          auth.uid() IS NOT NULL
          AND EXISTS (
            SELECT 1
            FROM user_saved_places usp
            INNER JOIN user_saved_place_folders usf
              ON usf.user_saved_place_id = usp.id
             AND usf.folder_key = p_situation_key
            WHERE usp.place_id = r.pid
              AND usp.user_id = auth.uid()
          )
        )
        OR (
          p_situation_key = 'after_party'
          AND (
            r.hay ~ '(2차|야간|늦게|포차|바|술집|안주|해산물|맥주|하이볼)'
            OR lower(coalesce(r.pcategory, '')) ~ '(주점|바|포장|민속|호프|술집|이자카야|와인|포차)'
          )
        )
        OR (
          p_situation_key = 'group'
          AND (
            r.hay ~ '(회식|단체|국물|고기|삼겹|밥|해장|곱창|찌개)'
            OR lower(coalesce(r.pcategory, '')) ~ '(한식|중식|일식|고기|곱창|삼겹|국밥|찌개|회)'
          )
        )
        OR (
          p_situation_key = 'date'
          AND (
            r.hay ~ '(데이트|분위기|로맨틱|와인|조용|야외|루프탑|뷰|인테리어)'
            OR lower(coalesce(r.pcategory, '')) ~ '(와인|바|카페|브루|다이닝|레스토랑|이탈리)'
          )
        )
      )
  )
  SELECT
    sp.pid,
    sp.pname,
    sp.pcategory,
    sp.plat,
    sp.plng,
    sp.sc
  FROM situation_pass sp
  ORDER BY sp.sc DESC, sp.pid
  LIMIT greatest(1, least(coalesce(p_limit, 120), 500));
$$;


--
-- Name: FUNCTION map_places_in_bbox(south double precision, west double precision, north double precision, east double precision, p_limit integer, p_situation_key text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.map_places_in_bbox(south double precision, west double precision, north double precision, east double precision, p_limit integer, p_situation_key text) IS '지도 bbox 안 장소: 큐레이터 연결 수 기반 score(가중치 튜닝 가능) + 선택적 상황키(after_party|group|date). 상황: 본인 저장 폴더 일치 OR places.tags·category 휴리스틱. 프론트 situationPlaceFilter.js 와 유사 규칙 — 완전 동일하진 않을 수 있음.';


--
-- Name: mutual_follow_with(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mutual_follow_with(p_other_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.user_profile_follows f
    WHERE f.follower_id = auth.uid()
      AND f.following_id = p_other_user_id
  )
  AND EXISTS (
    SELECT 1
    FROM public.user_profile_follows f
    WHERE f.follower_id = p_other_user_id
      AND f.following_id = auth.uid()
  );
$$;


--
-- Name: normalize_alpha_allowlist_email(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.normalize_alpha_allowlist_email() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  NEW.email := lower(trim(NEW.email));
  RETURN NEW;
END;
$$;


--
-- Name: peek_studio_ai_course_suggestion_for_user(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.peek_studio_ai_course_suggestion_for_user(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_limit integer := 5;
  v_used integer;
  v_pro boolean;
BEGIN
  IF p_user_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'allowed', false, 'reason', 'no_user');
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.curators c WHERE c.user_id = p_user_id
  ) THEN
    RETURN jsonb_build_object('ok', false, 'allowed', false, 'reason', 'not_curator');
  END IF;

  v_pro := public.is_studio_pro_curator(p_user_id);
  v_used := public._studio_ai_course_used_this_month(p_user_id);

  IF v_pro THEN
    RETURN jsonb_build_object(
      'ok', true,
      'allowed', true,
      'is_pro', true,
      'used', v_used,
      'remaining', NULL
    );
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'allowed', v_used < v_limit,
    'is_pro', false,
    'limit', v_limit,
    'used', v_used,
    'remaining', greatest(0, v_limit - v_used),
    'reason', CASE WHEN v_used >= v_limit THEN 'quota_exceeded' ELSE NULL END
  );
END;
$$;


--
-- Name: check_ins; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.check_ins (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_nickname character varying(100) NOT NULL,
    place_id character varying(255) NOT NULL,
    place_name character varying(255) NOT NULL,
    place_address text,
    created_at timestamp with time zone DEFAULT now(),
    distance_meters double precision,
    location_accuracy_m double precision,
    user_id uuid
);


--
-- Name: perform_check_in_nearby(text, text, text, text, double precision, double precision, double precision, double precision, double precision, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.perform_check_in_nearby(p_user_nickname text, p_place_id text, p_place_name text, p_place_address text, p_place_lat double precision, p_place_lng double precision, p_user_lat double precision, p_user_lng double precision, p_accuracy_m double precision DEFAULT NULL::double precision, p_skip_distance_check boolean DEFAULT false) RETURNS SETOF public.check_ins
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  dist double precision;
  allow_radius double precision;
  acc double precision;
  skip boolean;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'checkin_not_authenticated';
  END IF;

  skip := COALESCE(p_skip_distance_check, false);

  IF skip THEN
    RETURN QUERY
    INSERT INTO public.check_ins (
      user_id,
      user_nickname,
      place_id,
      place_name,
      place_address,
      distance_meters,
      location_accuracy_m
    )
    VALUES (
      auth.uid(),
      left(trim(p_user_nickname), 100),
      left(trim(p_place_id), 255),
      left(trim(p_place_name), 255),
      COALESCE(p_place_address, ''),
      NULL,
      NULL
    )
    RETURNING *;
    RETURN;
  END IF;

  IF p_place_lat IS NULL OR p_place_lng IS NULL THEN
    RAISE EXCEPTION 'checkin_place_coordinates_required';
  END IF;

  IF p_user_lat IS NULL OR p_user_lng IS NULL THEN
    RAISE EXCEPTION 'checkin_user_coordinates_required';
  END IF;

  IF p_place_lat < 32.5 OR p_place_lat > 43.5
     OR p_place_lng < 123.5 OR p_place_lng > 132.5 THEN
    RAISE EXCEPTION 'checkin_place_coordinates_invalid';
  END IF;

  acc := COALESCE(p_accuracy_m, 120.0);
  IF acc > 2500 THEN
    RAISE EXCEPTION 'checkin_location_accuracy_too_poor';
  END IF;

  dist := public.haversine_meters(
    p_place_lat, p_place_lng, p_user_lat, p_user_lng
  );

  allow_radius := 140.0 + least(acc, 280.0);

  IF dist > allow_radius THEN
    RAISE EXCEPTION 'checkin_too_far_from_place'
      USING DETAIL = format('distance_m=%s allow_m=%s', dist, allow_radius);
  END IF;

  RETURN QUERY
  INSERT INTO public.check_ins (
    user_id,
    user_nickname,
    place_id,
    place_name,
    place_address,
    distance_meters,
    location_accuracy_m
  )
  VALUES (
    auth.uid(),
    left(trim(p_user_nickname), 100),
    left(trim(p_place_id), 255),
    left(trim(p_place_name), 255),
    COALESCE(p_place_address, ''),
    dist,
    p_accuracy_m
  )
  RETURNING *;
END;
$$;


--
-- Name: FUNCTION perform_check_in_nearby(p_user_nickname text, p_place_id text, p_place_name text, p_place_address text, p_place_lat double precision, p_place_lng double precision, p_user_lat double precision, p_user_lng double precision, p_accuracy_m double precision, p_skip_distance_check boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.perform_check_in_nearby(p_user_nickname text, p_place_id text, p_place_name text, p_place_address text, p_place_lat double precision, p_place_lng double precision, p_user_lat double precision, p_user_lng double precision, p_accuracy_m double precision, p_skip_distance_check boolean) IS '한잔함(내부 체크인): 거리 검증 또는 skip. user_id=auth.uid() 기록.';


--
-- Name: place_picks_set_is_curator_before_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.place_picks_set_is_curator_before_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  NEW.is_curator := EXISTS (
    SELECT 1 FROM public.curators c WHERE c.user_id = NEW.user_id
  );
  NEW.updated_at := timezone('utc'::text, now());
  RETURN NEW;
END;
$$;


--
-- Name: place_picks_touch_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.place_picks_touch_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  NEW.updated_at := timezone('utc'::text, now());
  RETURN NEW;
END;
$$;


--
-- Name: prevent_curator_privileged_self_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_curator_privileged_self_update() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  privileged_changed boolean;
BEGIN
  privileged_changed :=
    NEW.grade IS DISTINCT FROM OLD.grade
    OR NEW.status IS DISTINCT FROM OLD.status
    OR NEW.warning_count IS DISTINCT FROM OLD.warning_count;

  IF NOT privileged_changed THEN
    RETURN NEW;
  END IF;

  IF auth.uid() IS NULL OR auth.role() = 'service_role' THEN
    RETURN NEW;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.profiles p
    WHERE p.id = auth.uid() AND p.role = 'admin'
  ) THEN
    RETURN NEW;
  END IF;

  RAISE EXCEPTION 'curator grade/status change not allowed (admin only)';
END;
$$;


--
-- Name: FUNCTION prevent_curator_privileged_self_update(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.prevent_curator_privileged_self_update() IS 'curators.grade/status/warning_count — admin 또는 service_role 만 변경 가능';


--
-- Name: prevent_profile_role_self_escalation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_profile_role_self_escalation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- role 변경이 없으면 통과 (닉네임·아바타 등 일반 수정)
  IF NEW.role IS NOT DISTINCT FROM OLD.role THEN
    RETURN NEW;
  END IF;

  -- 서버(service_role) 또는 JWT 없는 신뢰 컨텍스트 → 허용
  IF auth.uid() IS NULL OR auth.role() = 'service_role' THEN
    RETURN NEW;
  END IF;

  -- 그 외에는 호출자가 admin 일 때만 role 변경 허용
  IF EXISTS (
    SELECT 1 FROM public.profiles p
    WHERE p.id = auth.uid() AND p.role = 'admin'
  ) THEN
    RETURN NEW;
  END IF;

  RAISE EXCEPTION 'role change not allowed (admin only)';
END;
$$;


--
-- Name: FUNCTION prevent_profile_role_self_escalation(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.prevent_profile_role_self_escalation() IS 'profiles.role 자기승격 차단 — admin 또는 service_role 만 role 변경 가능';


--
-- Name: reject_curator_application(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_curator_application(application_id uuid, p_reason text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'auth required';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.profiles pr
    WHERE pr.id = auth.uid() AND pr.role = 'admin'
  ) THEN
    RAISE EXCEPTION 'admin only';
  END IF;

  UPDATE public.curator_applications
  SET
    status = 'rejected',
    rejection_reason = NULLIF(btrim(COALESCE(p_reason, '')), '')
  WHERE id = application_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'application not found';
  END IF;
END;
$$;


--
-- Name: resolve_curator_grade_review_on_grade(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_curator_grade_review_on_grade() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP <> 'UPDATE' OR NEW.grade IS NOT DISTINCT FROM OLD.grade THEN
    RETURN NEW;
  END IF;

  UPDATE public.curator_grade_review_queue q
  SET
    resolved_at = now(),
    resolved_action = 'applied'
  WHERE q.curator_user_id = NEW.user_id
    AND q.resolved_at IS NULL
    AND public.grade_rank(COALESCE(NEW.grade, 'bronze')) >= public.grade_rank(q.suggested_grade);

  RETURN NEW;
END;
$$;


--
-- Name: resolve_places_uuid_from_check_ins_place_id(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_places_uuid_from_check_ins_place_id(p_place_id text) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
  SELECT CASE
    WHEN btrim(COALESCE(p_place_id, '')) ~*
      '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      THEN btrim(p_place_id)::uuid
    ELSE (
      SELECT p.id
      FROM public.places p
      WHERE btrim(COALESCE(p.kakao_place_id::text, '')) = btrim(COALESCE(p_place_id::text, ''))
      LIMIT 1
    )
  END;
$_$;


--
-- Name: revoke_curator_application(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revoke_curator_application(application_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  applicant_user_id uuid;
  applicant_role text;
begin
  -- 1) 신청 정보와 현재 role 가져오기
  select ca.user_id, p.role into applicant_user_id, applicant_role
  from public.curator_applications ca
  join public.profiles p on ca.user_id = p.id
  where ca.id = application_id;

  if applicant_user_id is null then
    raise exception 'Application not found';
  end if;

  -- 2) admin이 아닌 경우에만 role을 'user'로 되돌리기
  if applicant_role != 'admin' then
    update public.profiles
    set role = 'user'
    where id = applicant_user_id;
  end if;

  -- 3) curators 테이블에서 삭제 (승인된 경우만)
  delete from public.curators
  where user_id = applicant_user_id;

  -- 4) 신청 상태를 'pending'으로 되돌리기
  update public.curator_applications
  set status = 'pending', updated_at = now()
  where id = application_id;
end;
$$;


--
-- Name: save_curator_place(uuid, text, text, text, double precision, double precision, text, text[], boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_curator_place(p_curator_id uuid, p_name text, p_address text, p_region text, p_lat double precision, p_lng double precision, p_comment text, p_tags text[], p_is_draft boolean DEFAULT false) RETURNS TABLE(success boolean, place_id uuid, message text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_place_id UUID;
    v_curator_id UUID;
BEGIN
    -- UUID 자동 생성
    v_place_id := gen_random_uuid();
    
    -- 큐레이터 ID 확인
    SELECT id INTO v_curator_id 
    FROM curators 
    WHERE user_id = p_curator_id;
    
    IF v_curator_id IS NULL THEN
        RETURN QUERY SELECT false, NULL::UUID, '큐레이터를 찾을 수 없습니다.';
        RETURN;
    END IF;
    
    -- 장소 추가 (UUID 자동 생성)
    INSERT INTO places (
        id, name, address, region, lat, lng, comment, tags, 
        primary_curator_id, saved_count, created_at
    ) VALUES (
        v_place_id, p_name, p_address, p_region, p_lat, p_lng, 
        p_comment, p_tags, v_curator_id, 0, NOW()
    );
    
    RETURN QUERY SELECT true, v_place_id, '장소가 성공적으로 추가되었습니다.';
END;
$$;


--
-- Name: save_curator_place(text, text, numeric, numeric, text, text, text, text[], text[], text[], text, text, text, text, integer, boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_curator_place(place_name text, address text, latitude numeric, longitude numeric, one_line_review text, phone text DEFAULT NULL::text, category text DEFAULT NULL::text, photos text[] DEFAULT '{}'::text[], tags text[] DEFAULT '{}'::text[], visit_situations text[] DEFAULT '{}'::text[], recommended_menu text DEFAULT NULL::text, price_range text DEFAULT NULL::text, visit_tips text DEFAULT NULL::text, notes text DEFAULT NULL::text, rating integer DEFAULT NULL::integer, is_public boolean DEFAULT false, is_featured boolean DEFAULT false) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  curator_id uuid;
  place_id uuid;
begin
  select id into curator_id
  from public.curators
  where user_id = auth.uid();
  
  if curator_id is null then
    raise exception 'Curator not found';
  end if;
  
  insert into public.places (
    name, address, latitude, longitude, phone, category, 
    curator_id, photos, notes, rating, tags, is_public, is_featured,
    one_line_review, visit_situations, recommended_menu, price_range, visit_tips
  )
  values (
    place_name, address, latitude, longitude, phone, category,
    curator_id, photos, notes, rating, tags, is_public, is_featured,
    one_line_review, visit_situations, recommended_menu, price_range, visit_tips
  )
  returning id into place_id;
  
  return place_id;
end;
$$;


--
-- Name: save_place_to_folders(uuid, uuid, text[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_place_to_folders(p_user_id uuid, p_place_id uuid, p_folder_keys text[], p_first_saved_from text DEFAULT 'home'::text) RETURNS TABLE(success boolean, message text, saved_place_id uuid)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_saved_place_id UUID;
    v_folder_key TEXT;
BEGIN
    -- 1. 장소 저장 (UPSERT)
    INSERT INTO user_saved_places (user_id, place_id, first_saved_from)
    VALUES (p_user_id, p_place_id, p_first_saved_from)
    ON CONFLICT (user_id, place_id) 
    DO UPDATE SET updated_at = NOW()
    RETURNING id INTO v_saved_place_id;
    
    -- 2. 폴더 연결 (기존 연결 삭제 후 새로 추가)
    DELETE FROM user_saved_place_folders 
    WHERE user_saved_place_id = v_saved_place_id;
    
    -- 3. 새 폴더 연결 추가
    FOREACH v_folder_key IN ARRAY p_folder_keys
    LOOP
        INSERT INTO user_saved_place_folders (user_saved_place_id, folder_key)
        VALUES (v_saved_place_id, v_folder_key);
    END LOOP;
    
    RETURN QUERY SELECT true, 'Successfully saved', v_saved_place_id;
EXCEPTION
    WHEN OTHERS THEN
        RETURN QUERY SELECT false, SQLERRM, NULL::UUID;
END;
$$;


--
-- Name: search_curator_places_trgm(text, uuid, integer, double precision, double precision, double precision); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_curator_places_trgm(p_query text, p_curator_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 40, p_max_distance_m double precision DEFAULT NULL::double precision, p_origin_lat double precision DEFAULT NULL::double precision, p_origin_lng double precision DEFAULT NULL::double precision) RETURNS TABLE(curator_place_id uuid, place_id uuid, text_score double precision, distance_m double precision)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    ranked.curator_place_id,
    ranked.place_id,
    ranked.text_score,
    ranked.distance_m
  FROM (
    SELECT
      cp.id AS curator_place_id,
      cp.place_id,
      GREATEST(
        similarity(
          public.curator_place_search_blob(cp),
          TRIM(COALESCE(p_query, ''))
        ),
        CASE
          WHEN public.curator_place_search_blob(cp) ILIKE '%' || TRIM(COALESCE(p_query, '')) || '%'
          THEN 0.25::double precision
          ELSE 0::double precision
        END
      ) AS text_score,
      CASE
        WHEN p_origin_lat IS NULL OR p_origin_lng IS NULL OR pl.lat IS NULL OR pl.lng IS NULL THEN NULL
        ELSE public.haversine_meters(
          p_origin_lat,
          p_origin_lng,
          pl.lat::double precision,
          pl.lng::double precision
        )
      END AS distance_m
    FROM public.curator_places cp
    INNER JOIN public.places pl ON pl.id = cp.place_id
    WHERE cp.is_archived = false
      AND (p_curator_id IS NULL OR cp.curator_id = p_curator_id)
      AND TRIM(COALESCE(p_query, '')) <> ''
      AND TRIM(public.curator_place_search_blob(cp)) <> ''
      AND (
        public.curator_place_search_blob(cp) ILIKE '%' || TRIM(p_query) || '%'
        OR similarity(
          public.curator_place_search_blob(cp),
          TRIM(COALESCE(p_query, ''))
        ) > 0.06
      )
  ) ranked
  WHERE
    p_max_distance_m IS NULL
    OR ranked.distance_m IS NULL
    OR ranked.distance_m <= p_max_distance_m
  ORDER BY ranked.text_score DESC NULLS LAST, ranked.distance_m ASC NULLS LAST
  LIMIT LEAST(GREATEST(COALESCE(p_limit, 40), 1), 200);
$$;


--
-- Name: search_curator_places_vector(public.vector, uuid, integer, double precision, double precision, double precision); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_curator_places_vector(p_query_embedding public.vector, p_curator_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 40, p_max_distance_m double precision DEFAULT NULL::double precision, p_origin_lat double precision DEFAULT NULL::double precision, p_origin_lng double precision DEFAULT NULL::double precision) RETURNS TABLE(curator_place_id uuid, place_id uuid, vector_score double precision, distance_m double precision)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    cp.id AS curator_place_id,
    cp.place_id,
    (1::double precision - (cp.one_line_embedding <=> p_query_embedding))::double precision AS vector_score,
    CASE
      WHEN p_origin_lat IS NULL OR p_origin_lng IS NULL OR pl.lat IS NULL OR pl.lng IS NULL THEN NULL
      ELSE public.haversine_meters(
        p_origin_lat,
        p_origin_lng,
        pl.lat::double precision,
        pl.lng::double precision
      )
    END AS distance_m
  FROM public.curator_places cp
  INNER JOIN public.places pl ON pl.id = cp.place_id
  WHERE cp.is_archived = false
    AND cp.one_line_embedding IS NOT NULL
    AND (p_curator_id IS NULL OR cp.curator_id = p_curator_id)
    AND (
      p_max_distance_m IS NULL
      OR pl.lat IS NULL
      OR pl.lng IS NULL
      OR p_origin_lat IS NULL
      OR p_origin_lng IS NULL
      OR public.haversine_meters(
        p_origin_lat,
        p_origin_lng,
        pl.lat::double precision,
        pl.lng::double precision
      ) <= p_max_distance_m
    )
  ORDER BY cp.one_line_embedding <=> p_query_embedding
  LIMIT LEAST(GREATEST(COALESCE(p_limit, 40), 1), 200);
$$;


--
-- Name: search_public_curator_courses(text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_public_curator_courses(p_query text, p_limit integer DEFAULT 24, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_q text;
  v_lim integer;
  v_off integer;
  v_pattern text;
  v_rows jsonb;
  v_has_more boolean;
  v_matched_count integer;
BEGIN
  v_q := btrim(coalesce(p_query, ''));
  IF char_length(v_q) < 1 THEN
    RETURN jsonb_build_object('courses', '[]'::jsonb, 'has_more', false);
  END IF;
  IF char_length(v_q) > 80 THEN
    v_q := left(v_q, 80);
  END IF;

  v_lim := greatest(1, least(coalesce(p_limit, 24), 50));
  v_off := greatest(0, coalesce(p_offset, 0));
  v_pattern := '%' || replace(replace(v_q, '%', ''), '_', '') || '%';

  WITH matched AS (
    SELECT
      cc.id,
      cc.curator_id,
      cc.title,
      cc.description,
      cc.cover_image_url,
      cc.area,
      cc.theme_tags,
      cc.status,
      cc.is_public,
      cc.created_at,
      cc.updated_at,
      (
        SELECT count(*)::integer
        FROM public.curator_course_places ccp
        WHERE ccp.course_id = cc.id
      ) AS place_count
    FROM public.curator_courses cc
    LEFT JOIN public.profiles p ON p.id = cc.curator_id
    WHERE cc.status = 'published'
      AND cc.is_public = true
      AND cc.imported_from_course_id IS NULL
      AND (
        cc.title ILIKE v_pattern
        OR coalesce(cc.area, '') ILIKE v_pattern
        OR coalesce(cc.description, '') ILIKE v_pattern
        OR EXISTS (
          SELECT 1
          FROM unnest(coalesce(cc.theme_tags, '{}'::text[])) AS t(tag)
          WHERE t.tag ILIKE v_pattern
        )
        OR coalesce(p.display_name, '') ILIKE v_pattern
        OR coalesce(p.username, '') ILIKE v_pattern
      )
    ORDER BY cc.updated_at DESC NULLS LAST, cc.created_at DESC
    LIMIT v_lim + 1
    OFFSET v_off
  ),
  counted AS (
    SELECT count(*)::integer AS c FROM matched
  ),
  page AS (
    SELECT * FROM matched LIMIT v_lim
  )
  SELECT
    (SELECT c FROM counted),
    coalesce((SELECT jsonb_agg(to_jsonb(p)) FROM page p), '[]'::jsonb)
  INTO v_matched_count, v_rows;

  v_has_more := coalesce(v_matched_count, 0) > v_lim;

  RETURN jsonb_build_object(
    'courses', coalesce(v_rows, '[]'::jsonb),
    'has_more', v_has_more
  );
END;
$$;


--
-- Name: FUNCTION search_public_curator_courses(p_query text, p_limit integer, p_offset integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.search_public_curator_courses(p_query text, p_limit integer, p_offset integer) IS '홈 코스 discovery 검색 — 공개 원본 코스만. limit+1로 has_more 판단.';


--
-- Name: studio_archive_extended_insights(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.studio_archive_extended_insights(p_curator_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL OR p_curator_id IS DISTINCT FROM auth.uid() THEN
    RETURN jsonb_build_object(
      'one_line_top', '[]'::jsonb,
      'style', jsonb_build_object(
        'alcohol', '[]'::jsonb,
        'moods', '[]'::jsonb,
        'tags', '[]'::jsonb,
        'categories', '[]'::jsonb,
        'meta', jsonb_build_object('schema_version', 2)
      ),
      'followers', jsonb_build_object(
        'saves_on_picks', 0,
        'distinct_savers', 0,
        'regions', '[]'::jsonb,
        'checkins_total', 0
      )
    );
  END IF;

  RETURN (
    WITH params AS (
      SELECT
        p_curator_id AS uid,
        (SELECT c.id FROM curators c WHERE c.user_id = p_curator_id LIMIT 1) AS curator_row_id
    ),
    my_curator_ids AS (
      SELECT DISTINCT x AS cid
      FROM unnest(
        ARRAY[
          (SELECT uid FROM params),
          (SELECT curator_row_id FROM params)
        ]::uuid[]
      ) AS u(x)
      WHERE x IS NOT NULL
    ),
    my_place_ids AS (
      SELECT DISTINCT cp.place_id AS pid
      FROM curator_places cp
      WHERE btrim(cp.curator_id::text) IN (SELECT btrim(cid::text) FROM my_curator_ids)
        AND (cp.is_archived IS NOT TRUE)
        AND cp.place_id IS NOT NULL
    ),
    style_pick_rows AS (
      SELECT
        ('cp-' || cp.id::text) AS source_id,
        cp.place_id,
        cp.alcohol_types,
        cp.moods,
        cp.tags,
        'pick'::text AS source_kind
      FROM curator_places cp
      WHERE btrim(cp.curator_id::text) IN (SELECT btrim(cid::text) FROM my_curator_ids)
        AND (cp.is_archived IS NOT TRUE)
        AND cp.place_id IS NOT NULL
    ),
    style_course_only_rows AS (
      SELECT
        ('cc-' || cc.id::text || '-' || ccp.place_id::text) AS source_id,
        ccp.place_id,
        cp_match.alcohol_types,
        cp_match.moods,
        cp_match.tags,
        'course_only'::text AS source_kind
      FROM curator_courses cc
      INNER JOIN curator_course_places ccp ON ccp.course_id = cc.id
      LEFT JOIN curator_places cp_match
        ON cp_match.place_id = ccp.place_id
       AND btrim(cp_match.curator_id::text) IN (SELECT btrim(cid::text) FROM my_curator_ids)
       AND (cp_match.is_archived IS NOT TRUE)
      WHERE btrim(cc.curator_id::text) IN (SELECT btrim(cid::text) FROM my_curator_ids)
        AND ccp.place_id IS NOT NULL
        AND NOT EXISTS (
          SELECT 1
          FROM curator_places cp2
          WHERE cp2.place_id = ccp.place_id
            AND btrim(cp2.curator_id::text) IN (SELECT btrim(cid::text) FROM my_curator_ids)
            AND (cp2.is_archived IS NOT TRUE)
        )
    ),
    style_broad_rows AS (
      SELECT source_id, place_id, alcohol_types, moods, tags, source_kind
      FROM style_pick_rows
      UNION ALL
      SELECT source_id, place_id, alcohol_types, moods, tags, source_kind
      FROM style_course_only_rows
    ),
    style_taste_rows AS (
      SELECT b.source_id, b.place_id, b.alcohol_types, b.moods, b.tags, b.source_kind
      FROM style_broad_rows b
      LEFT JOIN places p ON p.id = b.place_id
      WHERE b.source_kind = 'pick'
         OR cardinality(public.cp_str_arr_for_unnest(b.alcohol_types)) > 0
         OR cardinality(public.cp_str_arr_for_unnest(b.moods)) > 0
         OR NULLIF(trim(COALESCE(p.alcohol_type, '')), '') IS NOT NULL
         OR NULLIF(trim(COALESCE(p.atmosphere, '')), '') IS NOT NULL
    ),
    theme_tag_rows AS (
      SELECT
        ('ct-' || cc.id::text || '-' || trim(t.x)) AS source_id,
        trim(t.x) AS label
      FROM curator_courses cc
      CROSS JOIN LATERAL unnest(cc.theme_tags) AS t(x)
      WHERE btrim(cc.curator_id::text) IN (SELECT btrim(cid::text) FROM my_curator_ids)
        AND length(trim(t.x)) > 0
    ),
    style_meta AS (
      SELECT jsonb_build_object(
        'schema_version', 2,
        'pick_source_count', (SELECT COUNT(*)::int FROM style_pick_rows),
        'course_only_source_count', (SELECT COUNT(*)::int FROM style_course_only_rows),
        'theme_tag_source_count', (SELECT COUNT(*)::int FROM theme_tag_rows),
        'axes', jsonb_build_object(
          'alcohol', 'taste_rows',
          'moods', 'taste_rows',
          'tags', 'broad_rows_and_theme_tags',
          'categories', 'broad_rows'
        )
      ) AS j
    ),
    one_line_rows AS (
      SELECT DISTINCT ON (cp.place_id)
        cp.place_id,
        NULLIF(trim(cp.one_line_reason), '') AS line
      FROM curator_places cp
      WHERE btrim(cp.curator_id::text) IN (SELECT btrim(cid::text) FROM my_curator_ids)
        AND (cp.is_archived IS NOT TRUE)
        AND length(trim(coalesce(cp.one_line_reason, ''))) > 1
      ORDER BY cp.place_id, cp.created_at DESC NULLS LAST
    ),
    save_by_place AS (
      SELECT usp.place_id, COUNT(*)::bigint AS c
      FROM user_saved_places usp
      WHERE usp.place_id IN (SELECT pid FROM my_place_ids)
      GROUP BY usp.place_id
    ),
    one_line_top AS (
      SELECT COALESCE(
        (
          SELECT jsonb_agg(
            jsonb_build_object(
              'text', q.line,
              'saves', q.saves,
              'place_id', q.place_id,
              'place_name', q.place_name
            )
            ORDER BY q.saves DESC, char_length(q.line) ASC, q.place_name ASC
          )
          FROM (
            SELECT
              ol.place_id,
              ol.line,
              COALESCE(sb.c, 0)::bigint AS saves,
              COALESCE(NULLIF(trim(p.name), ''), '(이름 없음)')::text AS place_name
            FROM one_line_rows ol
            LEFT JOIN save_by_place sb ON sb.place_id = ol.place_id
            LEFT JOIN places p ON p.id = ol.place_id
            WHERE ol.line IS NOT NULL
            ORDER BY COALESCE(sb.c, 0) DESC, char_length(ol.line) ASC, COALESCE(NULLIF(trim(p.name), ''), '') ASC
            LIMIT 5
          ) q
        ),
        '[]'::jsonb
      ) AS j
    ),
    alc AS (
      SELECT s.label, COUNT(*)::bigint AS cnt
      FROM (
        SELECT DISTINCT
          spr.source_id AS cp_id,
          trim(u.x) AS label
        FROM style_taste_rows spr
        LEFT JOIN places p ON p.id = spr.place_id
        CROSS JOIN LATERAL unnest(
          array_cat(
            public.cp_str_arr_for_unnest(spr.alcohol_types),
            CASE
              WHEN p.id IS NULL OR NULLIF(trim(COALESCE(p.alcohol_type, '')), '') IS NULL THEN
                ARRAY[]::text[]
              ELSE
                ARRAY[trim(COALESCE(p.alcohol_type, ''))]
            END
          )
        ) AS u(x)
        WHERE length(trim(u.x)) > 0
      ) s
      GROUP BY s.label
    ),
    alc_tot AS (SELECT COALESCE(SUM(cnt), 0)::bigint AS t FROM alc),
    alc_pct AS (
      SELECT COALESCE(
        (
          SELECT jsonb_agg(
            jsonb_build_object(
              'label', a.label,
              'count', a.cnt,
              'pct', CASE
                WHEN (SELECT t FROM alc_tot) > 0
                THEN round(100 * a.cnt::numeric / (SELECT t FROM alc_tot))::int
                ELSE 0
              END
            )
            ORDER BY a.cnt DESC
          )
          FROM (SELECT * FROM alc ORDER BY cnt DESC LIMIT 8) a
        ),
        '[]'::jsonb
      ) AS j
    ),
    md AS (
      SELECT s.label, COUNT(*)::bigint AS cnt
      FROM (
        SELECT DISTINCT
          spr.source_id AS cp_id,
          trim(u.x) AS label
        FROM style_taste_rows spr
        LEFT JOIN places p ON p.id = spr.place_id
        CROSS JOIN LATERAL unnest(
          array_cat(
            public.cp_str_arr_for_unnest(spr.moods),
            CASE
              WHEN p.id IS NULL OR NULLIF(trim(COALESCE(p.atmosphere, '')), '') IS NULL THEN
                ARRAY[]::text[]
              ELSE
                ARRAY[trim(COALESCE(p.atmosphere, ''))]
            END
          )
        ) AS u(x)
        WHERE length(trim(u.x)) > 0
      ) s
      GROUP BY s.label
    ),
    md_tot AS (SELECT COALESCE(SUM(cnt), 0)::bigint AS t FROM md),
    md_pct AS (
      SELECT COALESCE(
        (
          SELECT jsonb_agg(
            jsonb_build_object(
              'label', m.label,
              'count', m.cnt,
              'pct', CASE
                WHEN (SELECT t FROM md_tot) > 0
                THEN round(100 * m.cnt::numeric / (SELECT t FROM md_tot))::int
                ELSE 0
              END
            )
            ORDER BY m.cnt DESC
          )
          FROM (SELECT * FROM md ORDER BY cnt DESC LIMIT 8) m
        ),
        '[]'::jsonb
      ) AS j
    ),
    tg AS (
      SELECT s.label, COUNT(*)::bigint AS cnt
      FROM (
        SELECT DISTINCT
          spr.source_id AS cp_id,
          trim(u.x) AS label
        FROM style_broad_rows spr
        LEFT JOIN places p ON p.id = spr.place_id
        CROSS JOIN LATERAL unnest(
          array_cat(
            public.cp_str_arr_for_unnest(spr.tags),
            public.cp_str_arr_for_unnest(
              CASE
                WHEN p.id IS NULL THEN '[]'::jsonb
                WHEN p.tags IS NULL THEN '[]'::jsonb
                ELSE to_jsonb(p.tags)
              END
            )
          )
        ) AS u(x)
        WHERE length(trim(u.x)) > 0

        UNION ALL

        SELECT DISTINCT source_id AS cp_id, label
        FROM theme_tag_rows
      ) s
      GROUP BY s.label
    ),
    tg_tot AS (SELECT COALESCE(SUM(cnt), 0)::bigint AS t FROM tg),
    tg_pct AS (
      SELECT COALESCE(
        (
          SELECT jsonb_agg(
            jsonb_build_object(
              'label', tgrow.label,
              'count', tgrow.cnt,
              'pct', CASE
                WHEN (SELECT t FROM tg_tot) > 0
                THEN round(100 * tgrow.cnt::numeric / (SELECT t FROM tg_tot))::int
                ELSE 0
              END
            )
            ORDER BY tgrow.cnt DESC
          )
          FROM (SELECT * FROM tg ORDER BY cnt DESC LIMIT 10) tgrow
        ),
        '[]'::jsonb
      ) AS j
    ),
    cat AS (
      SELECT trim(p.category) AS label, COUNT(*)::bigint AS cnt
      FROM style_broad_rows spr
      JOIN places p ON p.id = spr.place_id
      WHERE p.category IS NOT NULL
        AND length(trim(p.category)) > 0
        AND trim(p.category) <> ALL (ARRAY['미분류', '기타']::text[])
      GROUP BY 1
    ),
    cat_tot AS (SELECT COALESCE(SUM(cnt), 0)::bigint AS t FROM cat),
    cat_pct AS (
      SELECT COALESCE(
        (
          SELECT jsonb_agg(
            jsonb_build_object(
              'label', c.label,
              'count', c.cnt,
              'pct', CASE
                WHEN (SELECT t FROM cat_tot) > 0
                THEN round(100 * c.cnt::numeric / (SELECT t FROM cat_tot))::int
                ELSE 0
              END
            )
            ORDER BY c.cnt DESC
          )
          FROM (SELECT * FROM cat ORDER BY cnt DESC LIMIT 8) c
        ),
        '[]'::jsonb
      ) AS j
    ),
    follow_u AS (
      SELECT DISTINCT uf.user_id
      FROM user_follows uf, params p
      WHERE (
          p.curator_row_id IS NOT NULL
          AND btrim(uf.curator_id::text) = btrim(p.curator_row_id::text)
        )
        OR btrim(uf.curator_id::text) = btrim(p.uid::text)
    ),
    fol_saves AS (
      SELECT usp.user_id, usp.place_id
      FROM user_saved_places usp
      WHERE usp.place_id IN (SELECT pid FROM my_place_ids)
        AND usp.user_id IN (SELECT user_id FROM follow_u)
    ),
    fol_agg AS (
      SELECT
        (SELECT COUNT(*)::bigint FROM fol_saves) AS saves_on_picks,
        (SELECT COUNT(DISTINCT user_id)::bigint FROM fol_saves) AS distinct_savers
    ),
    reg AS (
      SELECT
        CASE
          WHEN p.address IS NULL OR btrim(p.address) = '' THEN
            COALESCE(NULLIF(btrim(p.name), ''), '기타')
          ELSE
            NULLIF(
              btrim(
                split_part(btrim(p.address), ' ', 1)
                || CASE
                  WHEN split_part(btrim(p.address), ' ', 2) <> ''
                  THEN ' ' || split_part(btrim(p.address), ' ', 2)
                  ELSE ''
                END
              ),
              ''
            )
        END AS region_label,
        COUNT(*)::bigint AS c
      FROM fol_saves fs
      JOIN places p ON p.id = fs.place_id
      GROUP BY 1
    ),
    reg_json AS (
      SELECT COALESCE(
        (
          SELECT jsonb_agg(
            jsonb_build_object('label', r.region_label, 'saves', r.c)
            ORDER BY r.c DESC
          )
          FROM (SELECT * FROM reg ORDER BY c DESC LIMIT 5) r
        ),
        '[]'::jsonb
      ) AS j
    ),
    checkin_cnt AS (
      SELECT COUNT(*)::bigint AS n
      FROM check_ins ci
      WHERE EXISTS (
          SELECT 1
          FROM places pl
          WHERE pl.id IN (SELECT pid FROM my_place_ids)
            AND (
              (
                pl.kakao_place_id IS NOT NULL
                AND btrim(pl.kakao_place_id) <> ''
                AND ci.place_id = pl.kakao_place_id
              )
              OR ci.place_id = pl.id::text
            )
        )
    )
    SELECT jsonb_build_object(
      'one_line_top', (SELECT j FROM one_line_top),
      'style', jsonb_build_object(
        'alcohol', (SELECT j FROM alc_pct),
        'moods', (SELECT j FROM md_pct),
        'tags', (SELECT j FROM tg_pct),
        'categories', (SELECT j FROM cat_pct),
        'meta', (SELECT j FROM style_meta)
      ),
      'followers', jsonb_build_object(
        'saves_on_picks', COALESCE((SELECT saves_on_picks FROM fol_agg), 0),
        'distinct_savers', COALESCE((SELECT distinct_savers FROM fol_agg), 0),
        'regions', (SELECT j FROM reg_json),
        'checkins_total', COALESCE((SELECT n FROM checkin_cnt), 0)
      )
    )
  );
END;
$$;


--
-- Name: FUNCTION studio_archive_extended_insights(p_curator_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.studio_archive_extended_insights(p_curator_id uuid) IS '잔 아카이브 인사이트 v2. style: pick+course_only(중복제거), taste축 분리, count+meta. ML은 get_curator_style_features 사용.';


--
-- Name: studio_curator_overlap_place_count(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.studio_curator_overlap_place_count(p_curator_id uuid) RETURNS integer
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL OR p_curator_id IS DISTINCT FROM auth.uid() THEN
    RETURN 0;
  END IF;

  RETURN (
    WITH my_curator_ids AS (
      SELECT DISTINCT cid
      FROM (
        SELECT p_curator_id AS cid
        UNION ALL
        SELECT c.id
        FROM public.curators c
        WHERE c.user_id = p_curator_id
        LIMIT 1
      ) s
      WHERE cid IS NOT NULL
    ),
    my_places AS (
      SELECT DISTINCT cp.place_id
      FROM curator_places cp
      WHERE cp.place_id IS NOT NULL
        AND btrim(cp.curator_id::text) IN (SELECT btrim(cid::text) FROM my_curator_ids)
        AND (cp.is_archived IS NOT TRUE)
    )
    SELECT COUNT(*)::integer
    FROM my_places mp
    WHERE EXISTS (
      SELECT 1
      FROM curator_places o
      WHERE o.place_id = mp.place_id
        AND btrim(o.curator_id::text) NOT IN (SELECT btrim(cid::text) FROM my_curator_ids)
        AND (o.is_archived IS NOT TRUE)
    )
  );
END;
$$;


--
-- Name: FUNCTION studio_curator_overlap_place_count(p_curator_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.studio_curator_overlap_place_count(p_curator_id uuid) IS '큐레이터 본인(auth): 내 추천 장소 중 다른 큐레이터도 추천한 place_id 개수 (잔 아카이브 겹침)';


--
-- Name: studio_curator_overlap_places(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.studio_curator_overlap_places(p_curator_id uuid) RETURNS TABLE(place_id uuid, place_name text, place_address text, other_curator_handles text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL OR p_curator_id IS DISTINCT FROM auth.uid() THEN
    RETURN;
  END IF;

  RETURN QUERY
  WITH my_curator_ids AS (
    SELECT DISTINCT cid
    FROM (
      SELECT p_curator_id AS cid
      UNION ALL
      SELECT c.id
      FROM public.curators c
      WHERE c.user_id = p_curator_id
      LIMIT 1
    ) s
    WHERE cid IS NOT NULL
  ),
  my_places AS (
    SELECT DISTINCT cp.place_id AS pid
    FROM curator_places cp
    WHERE cp.place_id IS NOT NULL
      AND btrim(cp.curator_id::text) IN (SELECT btrim(cid::text) FROM my_curator_ids)
      AND (cp.is_archived IS NOT TRUE)
  ),
  overlap_place_ids AS (
    SELECT DISTINCT mp.pid
    FROM my_places mp
    WHERE EXISTS (
      SELECT 1
      FROM curator_places o
      WHERE o.place_id = mp.pid
        AND o.curator_id NOT IN (SELECT cid FROM my_curator_ids)
        AND (o.is_archived IS NOT TRUE)
    )
  )
  SELECT
    p.id,
    COALESCE(NULLIF(trim(p.name), ''), '(이름 없음)')::text,
    COALESCE(NULLIF(trim(p.address), ''), '')::text,
    (
      SELECT string_agg(sub.line, ', ' ORDER BY sub.gr DESC, sub.handle_key)
      FROM (
        SELECT DISTINCT ON (r.curator_id)
          (r.grade_ko || ' ' || r.handle_str) AS line,
          public.grade_rank(r.grade_raw) AS gr,
          r.handle_str AS handle_key
        FROM (
          SELECT
            o.curator_id,
            CASE lower(trim(COALESCE(cu.grade, 'bronze')))
              WHEN 'diamond' THEN '다이아몬드'
              WHEN 'platinum' THEN '플래티넘'
              WHEN 'gold' THEN '골드'
              WHEN 'silver' THEN '실버'
              WHEN 'bronze' THEN '브론즈'
              ELSE initcap(lower(trim(COALESCE(cu.grade, 'bronze'))))
            END AS grade_ko,
            COALESCE(cu.grade, 'bronze') AS grade_raw,
            CASE
              WHEN NULLIF(trim(cu.username), '') IS NOT NULL THEN
                '@' || trim(cu.username)
              WHEN NULLIF(trim(cu.slug), '') IS NOT NULL THEN
                '@' || trim(cu.slug)
              WHEN NULLIF(trim(cu.display_name), '') IS NOT NULL THEN
                trim(cu.display_name)
              ELSE
                'uid:' || LEFT(o.curator_id::text, 8)
            END AS handle_str
          FROM curator_places o
          LEFT JOIN LATERAL (
            SELECT c.*
            FROM public.curators c
            WHERE c.user_id = o.curator_id OR c.id = o.curator_id
            ORDER BY CASE WHEN c.user_id = o.curator_id THEN 0 ELSE 1 END
            LIMIT 1
          ) cu ON true
          WHERE o.place_id = p.id
            AND o.curator_id NOT IN (SELECT cid FROM my_curator_ids)
            AND (o.is_archived IS NOT TRUE)
        ) r
        ORDER BY r.curator_id
      ) sub
      WHERE sub.line IS NOT NULL AND trim(sub.line) <> ''
    )::text
  FROM public.places p
  INNER JOIN overlap_place_ids x ON x.pid = p.id
  ORDER BY p.name NULLS LAST;
END;
$$;


--
-- Name: FUNCTION studio_curator_overlap_places(p_curator_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.studio_curator_overlap_places(p_curator_id uuid) IS '본인(auth): 겹친 추천 장소 + 다른 큐레이터(한글 등급+핸들, curator user_id/id 조인, 등급 높은 순)';


--
-- Name: studio_delete_own_custom_folder(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.studio_delete_own_custom_folder(p_folder_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  uid uuid := auth.uid();
  curator_pk uuid;
  place_ids uuid[];
BEGIN
  IF uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not authenticated');
  END IF;

  IF p_folder_key IS NULL OR p_folder_key !~ '^custom_[0-9]+$' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid folder key');
  END IF;

  SELECT c.id
  INTO curator_pk
  FROM public.curators c
  WHERE c.user_id = uid
  LIMIT 1;

  SELECT COALESCE(
    (
      SELECT array_agg(DISTINCT usp.place_id)
      FROM public.user_saved_place_folders uspf
      INNER JOIN public.user_saved_places usp ON usp.id = uspf.user_saved_place_id
      WHERE uspf.folder_key = p_folder_key
        AND usp.place_id IS NOT NULL
        AND (
          usp.user_id = uid
          OR (curator_pk IS NOT NULL AND usp.user_id = curator_pk)
        )
    ),
    ARRAY[]::uuid[]
  )
  INTO place_ids;

  DELETE FROM public.user_saved_places usp
  USING public.user_saved_place_folders uspf
  WHERE usp.id = uspf.user_saved_place_id
    AND uspf.folder_key = p_folder_key
    AND (
      usp.user_id = uid
      OR (curator_pk IS NOT NULL AND usp.user_id = curator_pk)
    );

  IF cardinality(place_ids) > 0 THEN
    DELETE FROM public.curator_places cp
    WHERE cp.place_id = ANY (place_ids)
      AND cp.curator_id = uid;
  END IF;

  DELETE FROM public.system_folders sf
  WHERE sf.key = p_folder_key
    AND sf.key ~ '^custom_[0-9]+$'
    AND (
      sf.created_by = uid
      OR sf.created_by IS NULL
      OR (curator_pk IS NOT NULL AND sf.created_by = curator_pk)
    )
    AND NOT EXISTS (
      SELECT 1
      FROM public.user_saved_place_folders u2
      WHERE u2.folder_key = sf.key
    );

  RETURN jsonb_build_object(
    'ok', true,
    'deleted_place_ids', to_jsonb(place_ids)
  );
END;
$_$;


--
-- Name: FUNCTION studio_delete_own_custom_folder(p_folder_key text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.studio_delete_own_custom_folder(p_folder_key text) IS '본인 custom_* 폴더: 해당 폴더 링크된 user_saved_places 삭제(CASCADE로 uspf 정리), 관련 curator_places 삭제, 남은 링크 없으면 system_folders 삭제';


--
-- Name: studio_follower_previews(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.studio_follower_previews(p_curator_id uuid) RETURNS TABLE(user_id uuid, created_at timestamp with time zone, display_nick text, handle_raw text, avatar_url text, is_curator boolean, curator_grade text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    uf.follower_id AS user_id,
    uf.created_at,
    NULLIF(
      TRIM(
        COALESCE(
          NULLIF(TRIM(COALESCE(c.display_name, '')), ''),
          NULLIF(TRIM(COALESCE(c.name, '')), ''),
          NULLIF(TRIM(COALESCE(p.display_name, '')), '')
        )
      ),
      ''
    ) AS display_nick,
    NULLIF(
      LOWER(
        REGEXP_REPLACE(
          TRIM(COALESCE(c.username, p.username, '')),
          '^@+',
          ''
        )
      ),
      ''
    ) AS handle_raw,
    NULLIF(
      TRIM(COALESCE(c.avatar_url, p.avatar_url, '')),
      ''
    ) AS avatar_url,
    (c.user_id IS NOT NULL) AS is_curator,
    c.grade::text AS curator_grade
  FROM public.user_profile_follows uf
  INNER JOIN public.curators target ON btrim(target.id::text) = btrim(p_curator_id::text)
    AND uf.following_id = target.user_id
  LEFT JOIN public.profiles p ON p.id = uf.follower_id
  LEFT JOIN public.curators c ON c.user_id = uf.follower_id
  WHERE EXISTS (
    SELECT 1
    FROM public.curators owner
    WHERE btrim(owner.id::text) = btrim(p_curator_id::text)
      AND owner.user_id = auth.uid()
  )
  ORDER BY uf.created_at DESC
  LIMIT 200;
$$;


--
-- Name: studio_follower_previews_by_following(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.studio_follower_previews_by_following(p_following_user_id uuid) RETURNS TABLE(user_id uuid, created_at timestamp with time zone, display_nick text, handle_raw text, avatar_url text, is_curator boolean, curator_grade text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    uf.follower_id AS user_id,
    uf.created_at,
    NULLIF(
      TRIM(
        COALESCE(
          NULLIF(TRIM(COALESCE(c.display_name, '')), ''),
          NULLIF(TRIM(COALESCE(c.name, '')), ''),
          NULLIF(TRIM(COALESCE(p.display_name, '')), '')
        )
      ),
      ''
    ) AS display_nick,
    NULLIF(
      LOWER(
        REGEXP_REPLACE(
          TRIM(COALESCE(c.username, p.username, '')),
          '^@+',
          ''
        )
      ),
      ''
    ) AS handle_raw,
    NULLIF(
      TRIM(COALESCE(c.avatar_url, p.avatar_url, '')),
      ''
    ) AS avatar_url,
    (c.user_id IS NOT NULL) AS is_curator,
    c.grade::text AS curator_grade
  FROM public.user_profile_follows uf
  LEFT JOIN public.profiles p ON p.id = uf.follower_id
  LEFT JOIN public.curators c ON c.user_id = uf.follower_id
  WHERE uf.following_id = p_following_user_id
    AND p_following_user_id = auth.uid()
  ORDER BY uf.created_at DESC
  LIMIT 200;
$$;


--
-- Name: studio_following_previews(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.studio_following_previews(p_user_id uuid) RETURNS TABLE(curator_id_raw text, created_at timestamp with time zone, curator_user_id uuid, following_user_id uuid, display_nick text, handle_raw text, avatar_url text, curator_grade text, is_curator boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH base AS (
    SELECT f.following_id, f.created_at
    FROM public.user_profile_follows f
    WHERE f.follower_id = p_user_id
  ),
  dedup AS (
    SELECT DISTINCT ON (b.following_id)
      b.following_id,
      b.created_at
    FROM base b
    ORDER BY b.following_id, b.created_at DESC
  )
  SELECT
    btrim(cu.id::text) AS curator_id_raw,
    d.created_at,
    cu.user_id AS curator_user_id,
    d.following_id AS following_user_id,
    NULLIF(
      TRIM(
        COALESCE(
          NULLIF(TRIM(COALESCE(cu.display_name, '')), ''),
          NULLIF(TRIM(COALESCE(cu.name, '')), ''),
          NULLIF(TRIM(COALESCE(pr.display_name, '')), '')
        )
      ),
      ''
    ) AS display_nick,
    NULLIF(
      LOWER(REGEXP_REPLACE(TRIM(COALESCE(cu.username, pr.username, '')), '^@+', '')),
      ''
    ) AS handle_raw,
    NULLIF(TRIM(COALESCE(cu.avatar_url, pr.avatar_url, '')), '') AS avatar_url,
    cu.grade::text AS curator_grade,
    (cu.id IS NOT NULL) AS is_curator
  FROM dedup d
  LEFT JOIN public.curators cu ON cu.user_id = d.following_id
  LEFT JOIN public.profiles pr ON pr.id = d.following_id AND cu.id IS NULL
  WHERE p_user_id IS NOT DISTINCT FROM auth.uid()
  ORDER BY d.created_at DESC
  LIMIT 200;
$$;


--
-- Name: FUNCTION studio_following_previews(p_user_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.studio_following_previews(p_user_id uuid) IS 'Picks tab: users this follower_id follows; curator row when applicable else profile.';


--
-- Name: studio_normalize_place_category(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.studio_normalize_place_category(p_raw text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE
    WHEN p_raw IS NULL OR btrim(p_raw) = '' THEN '미분류'::text
    WHEN btrim(p_raw) IN (
      '한식', '중식', '일식', '양식', '육류', '해산물', '디저트', '술집·바', '미분류'
    ) THEN btrim(p_raw)
    WHEN lower(btrim(p_raw)) ~ '(중식|짜장|짬뽕)' THEN '중식'::text
    WHEN lower(btrim(p_raw)) ~ '(일식|돈까스|돈가스|라멘|라면|우동|일본|오마카세|스시|초밥)' THEN '일식'::text
    WHEN lower(btrim(p_raw)) ~ '(양식|파스타|피자|스테이크|프렌치|이탈리아|브런치|버거)' THEN '양식'::text
    WHEN lower(btrim(p_raw)) ~ '(해산물|횟집|회집|생선회|생선|조개|새우|사시미|참치|해물|오징어|게장|물회|수산|회전)' THEN '해산물'::text
    WHEN lower(btrim(p_raw)) ~ '(디저트|카페|베이커리|케이크|빵|커피|아이스크림|도넛)' THEN '디저트'::text
    WHEN lower(btrim(p_raw)) ~ '(술집|와인바|와인|이자카야|호프|주점|펍|포장마차|포차|루프탑|야장|칵테일|클럽|라운지|노포|실내포장|야외포장|테라스|요리주점|맥주|소주)' THEN '술집·바'::text
    WHEN lower(btrim(p_raw)) ~ '(돼지|소고기|고기|구이|삼겹|갈비|육류|닭|치킨|족발|보쌈|곱창|막창)' THEN '육류'::text
    WHEN lower(btrim(p_raw)) ~ '(한식|국밥|탕|찌개|순대|감자탕|설렁탕|해장|국수|냉면|비빔밥|순두부|곰탕|백반|죽|한우|밥집)' THEN '한식'::text
    WHEN lower(btrim(p_raw)) ~ '(슈퍼|마트|편의점|이마트)' THEN '미분류'::text
    WHEN lower(btrim(p_raw)) ~ '순대' THEN '한식'::text
    ELSE '미분류'::text
  END;
$$;


--
-- Name: FUNCTION studio_normalize_place_category(p_raw text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.studio_normalize_place_category(p_raw text) IS 'Kakao category_name 등 → Studio 잔 올리기 표준 업종 (places.category 저장·아카이브 집계와 맞춤)';


