CREATE FUNCTION public.studio_patch_curator_place_taxonomy(p_place_id uuid, p_tags jsonb DEFAULT '[]'::jsonb, p_moods jsonb DEFAULT '[]'::jsonb, p_alcohol_types jsonb DEFAULT '[]'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN;
  END IF;
  IF p_place_id IS NULL THEN
