--
-- Name: studio_week_save_insights(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.studio_week_save_insights(p_curator_id uuid) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL OR p_curator_id IS DISTINCT FROM auth.uid() THEN
    RETURN json_build_object(
      'top_place_name', NULL,
      'top_save_count', 0,
      'week_total_saves', 0
    );
  END IF;

  RETURN (
    WITH week_start AS (
      SELECT date_trunc('week', (now() AT TIME ZONE 'utc')) AT TIME ZONE 'utc' AS t
    ),
    my_places AS (
      SELECT cp.place_id
      FROM curator_places cp
      WHERE cp.curator_id = p_curator_id
        AND (cp.is_archived IS NOT TRUE)
    ),
    saves AS (
      SELECT usp.place_id, COUNT(*)::bigint AS c
      FROM user_saved_places usp
      CROSS JOIN week_start w
      WHERE usp.place_id IN (SELECT place_id FROM my_places)
        AND usp.created_at >= w.t
      GROUP BY usp.place_id
    ),
    top_one AS (
      SELECT COALESCE(NULLIF(trim(p.name), ''), NULLIF(trim(p.address), ''), '이름 없음') AS pname, s.c
      FROM saves s
      JOIN places p ON p.id = s.place_id
      ORDER BY s.c DESC, pname ASC NULLS LAST
      LIMIT 1
    )
    SELECT json_build_object(
      'top_place_name', (SELECT pname FROM top_one),
      'top_save_count', COALESCE((SELECT c FROM top_one), 0),
      'week_total_saves', COALESCE((SELECT SUM(c) FROM saves), 0)
    )
  );
END;
$$;


--
-- Name: FUNCTION studio_week_save_insights(p_curator_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.studio_week_save_insights(p_curator_id uuid) IS '큐레이터 본인(auth)의 추천 장소에 달린 이번 주(UTC 주 시작) user_saved_places 건수 합계 및 최다 장소';


--
-- Name: sync_curator_followers_count(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_curator_followers_count() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
begin
  if (tg_op = 'INSERT') then
    update public.curators
      set followers_count = followers_count + 1
    where id = new.curator_id;
    return new;
  elsif (tg_op = 'DELETE') then
    update public.curators
      set followers_count = greatest(followers_count - 1, 0)
    where id = old.curator_id;
    return old;
  end if;

  return null;
end;
$$;


--
-- Name: trg_audit_curator_applications(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_audit_curator_applications() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  actor uuid := auth.uid();
BEGIN
  IF actor IS NULL THEN
    IF TG_OP = 'DELETE' THEN
      RETURN OLD;
    END IF;
    RETURN NEW;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.profiles pr
    WHERE pr.id = actor AND pr.role = 'admin'
  ) THEN
    IF TG_OP = 'DELETE' THEN
      RETURN OLD;
    END IF;
    RETURN NEW;
  END IF;

  IF TG_OP = 'DELETE' THEN
    PERFORM public.admin_audit_log_insert_definer(
      actor,
      'application_deleted',
      OLD.user_id,
      jsonb_build_object(
        'application_id', OLD.id,
        'name', OLD.name,
        'was_approved', (OLD.status = 'approved')
      )
    );
    RETURN OLD;
  END IF;

  IF TG_OP = 'UPDATE' AND OLD.status IS DISTINCT FROM NEW.status THEN
    IF NEW.status = 'approved' THEN
      PERFORM public.admin_audit_log_insert_definer(
        actor,
        'application_approved',
        NEW.user_id,
        jsonb_build_object(
          'application_id', NEW.id,
          'name', NEW.name
        )
      );
    ELSIF NEW.status = 'rejected' THEN
      PERFORM public.admin_audit_log_insert_definer(
        actor,
        'application_rejected',
        NEW.user_id,
        jsonb_build_object(
          'application_id', NEW.id,
          'name', NEW.name,
          'reason', NEW.rejection_reason
        )
      );
    ELSIF NEW.status = 'pending' AND OLD.status = 'approved' THEN
      PERFORM public.admin_audit_log_insert_definer(
        actor,
        'application_revoke_curator',
        NEW.user_id,
        jsonb_build_object(
          'application_id', NEW.id,
          'name', NEW.name
        )
      );
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: trg_audit_curators_admin(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_audit_curators_admin() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  actor uuid := auth.uid();
BEGIN
  IF actor IS NULL THEN
    IF TG_OP = 'DELETE' THEN
      RETURN OLD;
    END IF;
    RETURN NEW;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.profiles pr
    WHERE pr.id = actor AND pr.role = 'admin'
  ) THEN
    IF TG_OP = 'DELETE' THEN
      RETURN OLD;
    END IF;
    RETURN NEW;
  END IF;

  IF TG_OP = 'DELETE' THEN
    PERFORM public.admin_audit_log_insert_definer(
      actor,
      'curator_revoked',
      OLD.user_id,
      jsonb_build_object('username', OLD.username)
    );
    RETURN OLD;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    IF OLD.grade IS DISTINCT FROM NEW.grade THEN
      PERFORM public.admin_audit_log_insert_definer(
        actor,
        'curator_grade_changed',
        NEW.user_id,
        jsonb_build_object('from', OLD.grade, 'to', NEW.grade)
      );
    END IF;
    IF OLD.status IS DISTINCT FROM NEW.status THEN
      PERFORM public.admin_audit_log_insert_definer(
        actor,
        'curator_status_changed',
        NEW.user_id,
        jsonb_build_object('from', OLD.status, 'to', NEW.status)
      );
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: trg_audit_grade_review_dismissed(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_audit_grade_review_dismissed() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  actor uuid := auth.uid();
BEGIN
  IF actor IS NULL THEN
    RETURN NEW;
