    PERFORM public.admin_audit_log_insert_definer(
      actor,
      'grade_review_dismissed',
      NEW.curator_user_id,
      jsonb_build_object(
        'queue_id', NEW.id,
        'via', 'queue'
      )
    );
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: try_consume_studio_ai_course_suggestion_for_user(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.try_consume_studio_ai_course_suggestion_for_user(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_limit integer := 5;
  v_used integer;
  v_pro boolean;
BEGIN
  IF p_user_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'allowed', false, 'reason', 'no_user');
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.curators c WHERE c.user_id = p_user_id
  ) THEN
    RETURN jsonb_build_object('ok', false, 'allowed', false, 'reason', 'not_curator');
  END IF;

  v_pro := public.is_studio_pro_curator(p_user_id);
  IF v_pro THEN
    INSERT INTO public.curator_studio_ai_usage (curator_id, feature)
    VALUES (p_user_id, 'ai_course_suggestion');
    RETURN jsonb_build_object(
      'ok', true,
      'allowed', true,
      'is_pro', true,
      'used', public._studio_ai_course_used_this_month(p_user_id),
      'remaining', NULL
    );
  END IF;

  v_used := public._studio_ai_course_used_this_month(p_user_id);
  IF v_used >= v_limit THEN
    RETURN jsonb_build_object(
      'ok', true,
      'allowed', false,
      'is_pro', false,
      'reason', 'quota_exceeded',
      'limit', v_limit,
      'used', v_used,
      'remaining', 0
    );
  END IF;

  INSERT INTO public.curator_studio_ai_usage (curator_id, feature)
  VALUES (p_user_id, 'ai_course_suggestion');

  RETURN jsonb_build_object(
    'ok', true,
    'allowed', true,
    'is_pro', false,
    'limit', v_limit,
    'used', v_used + 1,
    'remaining', greatest(0, v_limit - v_used - 1)
  );
END;
$$;


--
-- Name: FUNCTION try_consume_studio_ai_course_suggestion_for_user(p_user_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.try_consume_studio_ai_course_suggestion_for_user(p_user_id uuid) IS '서버 전용: AI 코스 초안 1회 차감 후 allowed 여부 반환.';


--
-- Name: try_exchange_drops_for_ai_credit(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.try_exchange_drops_for_ai_credit(p_user_id uuid DEFAULT auth.uid()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := p_user_id;
  v_per integer := public._drops_per_ai_credit();
  v_drops integer;
  v_credits integer;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'message', '로그인이 필요해요.');
  END IF;

  PERFORM public._ensure_user_wallet(v_uid);

  SELECT w.drop_balance, w.ai_credit_balance
  INTO v_drops, v_credits
  FROM public.user_wallets w
  WHERE w.user_id = v_uid
  FOR UPDATE;

  IF COALESCE(v_drops, 0) < v_per THEN
    RETURN jsonb_build_object(
      'ok', false,
      'message', format('Drop이 %s개 더 필요해요.', v_per - COALESCE(v_drops, 0)),
      'wallet', public.get_user_wallet(v_uid)
    );
  END IF;

  UPDATE public.user_wallets
  SET
    drop_balance = drop_balance - v_per,
    ai_credit_balance = ai_credit_balance + 1,
    updated_at = now()
  WHERE user_id = v_uid;

  INSERT INTO public.user_drop_ledger (user_id, delta, reason, ref_type)
  VALUES (v_uid, -v_per, 'exchange_ai_credit', 'ai_credit');

  RETURN jsonb_build_object(
    'ok', true,
    'wallet', public.get_user_wallet(v_uid)
  );
END;
$$;


