);


--
-- Name: TABLE activation_funnel_logs; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.activation_funnel_logs IS 'first session activation funnel logs. client INSERT only. admin SELECT only.';


--
-- Name: active_course_sessions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.active_course_sessions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    course_id uuid NOT NULL,
    current_step_index integer DEFAULT 0 NOT NULL,
