    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    completed_at timestamp with time zone,
    abandoned_at timestamp with time zone,
    CONSTRAINT active_course_sessions_completed_xor_abandoned_check CHECK ((NOT ((completed_at IS NOT NULL) AND (abandoned_at IS NOT NULL)))),
    CONSTRAINT active_course_sessions_step_nonnegative_check CHECK ((current_step_index >= 0))
);


--
-- Name: TABLE active_course_sessions; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.active_course_sessions IS '공개 코스 따라가기 진행 세션. 사용자당 동시에 하나의 active 세션만 (completed/abandoned 가 아닌 행). 체크인 연동은 추후.';


--
-- Name: admin_audit_log; Type: TABLE; Schema: public; Owner: -
--

