);


--
-- Name: TABLE admin_audit_log; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.admin_audit_log IS '관리자 운영 감사 로그. INSERT: append_admin_audit_log(RPC) 또는 admin_audit_log_insert_definer(트리거 전용).';


--
-- Name: admin_audit_log_id_seq; Type: SEQUENCE; Schema: public; Owner: -
--

ALTER TABLE public.admin_audit_log ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.admin_audit_log_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


--
-- Name: alpha_access_allowlist; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.alpha_access_allowlist (
    email text NOT NULL,
