    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE alpha_access_allowlist; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.alpha_access_allowlist IS '클로즈드 알파 초대 이메일. 소문자로 정규화되어 저장됩니다.';


--
-- Name: alpha_survey_responses; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.alpha_survey_responses (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    survey_version text DEFAULT 'v1'::text NOT NULL,
    answers jsonb DEFAULT '{}'::jsonb NOT NULL,
    submitted_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
