);


--
-- Name: TABLE alpha_survey_responses; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.alpha_survey_responses IS '알파 배포 피드백 설문 — 사용자별 최신 답변(버전당 1행 upsert).';


--
-- Name: COLUMN alpha_survey_responses.submitted_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.alpha_survey_responses.submitted_at IS 'NULL = 자동 임시저장(작성 중), NOT NULL = 사용자가 제출 완료';


--
-- Name: checkins; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.checkins (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
