    CONSTRAINT curator_courses_imported_snapshot_private_check CHECK (((imported_from_course_id IS NULL) OR ((status = ANY (ARRAY['draft'::text, 'private'::text])) AND (is_public = false)))),
    CONSTRAINT curator_courses_is_public_implies_published_check CHECK (((NOT is_public) OR (status = 'published'::text))),
    CONSTRAINT curator_courses_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'published'::text, 'private'::text]))),
    CONSTRAINT curator_courses_title_nonempty_check CHECK ((char_length(TRIM(BOTH FROM title)) > 0))
);


